import { useEffect, useState, type ReactNode } from "react";
import { ArrowUp, Bookmark, Bot, Boxes, CalendarCheck, ChartColumn, Check, CodeXml, Compass, Eye, Flag, Hand, History, KeyRound, LayoutGrid, Lightbulb, List, Palette, Search, Share2, ShieldCheck, GripVertical, Layers, ListChecks, MousePointerClick, Pencil, Plus, Sparkles, Tag, ThumbsUp, Users, Workflow } from "lucide-react";
import { STEP_META, STEP_TYPES } from "../lib/stepMeta";
import { aiFlow, automationFlow, changeFlow, feedbackFlow, followFlow, meaningFlow, memberFlow, requestFlow, reviewFlow, rightsFlow, signInFlow, standardFlow, themeFlow, versionFlow } from "../guide/flows";
import { ProcessPicture } from "./ProcessPicture";
import { Modal, scrollBehavior, scrollToStart, TypeIcon } from "./ui";

const GROUPS: { title: string; items: [string, string][] }[] = [
  { title: "Using it", items: [
    ["what", "What it is"],
    ["find", "Finding a process or standard"],
    ["modes", "Signing in and your rights"],
    ["belong", "Teams, platforms and practices"],
    ["group", "The page of a team, platform or practice"],
    ["read", "Reading a process"],
    ["follow", "Following a process"],
    ["blocks", "The building blocks"],
    ["standards", "Reading a standard"],
    ["feedback", "Feedback"],
    ["bookmarks", "Bookmarks, upvotes and sharing"],
    ["requests", "Asking for what is missing"],
    ["mine", "Your responsibilities"],
  ] },
  { title: "Editing", items: [
    ["editing", "The editing screen"],
    ["publish", "Drafts and publishing"],
    ["edit", "Editing a process"],
    ["editstandard", "Editing a standard"],
    ["versions", "Versions, undo and working together"],
    ["ai", "Creating one with AI"],
    ["lifecycle", "Life-cycle and reviews"],
  ] },
  { title: "For AI assistants", items: [
    ["skills", "Skills and review agents"],
    ["agents", "For agents: the MCP server"],
    ["roadmap", "Planned: automation"],
  ] },
  { title: "Administration", items: [
    ["admin", "The Admin panel"],
    ["theming", "The look of the portal"],
    ["catalog", "The lists"],
    ["codemap", "The code map"],
  ] },
  { title: "Running it", items: [
    ["architecture", "How it is built"],
    ["local", "Running it locally"],
    ["tests", "Tests"],
    ["deploy", "Deploying"],
    ["files", "Files, schema and checker"],
    ["docs", "Keeping this guide current"],
  ] },
];
const SECTIONS = GROUPS.flatMap((g) => g.items);

function Section({ id, title, children }: { id: string; title: string; children: ReactNode }) {
  return (
    <section id={`guide-${id}`} className="guide-section">
      <h2>{title}</h2>
      {children}
      <button type="button" className="guide-top link-btn" onClick={() => window.scrollTo({ top: 0, behavior: scrollBehavior() })}><ArrowUp size={14} /> Back to top</button>
    </section>
  );
}

/** The list of sections, beside the guide on a wide screen and in the Contents sheet on a narrow one. */
function Contents({ active, onPick }: { active: string; onPick: (id: string) => void }) {
  return GROUPS.map((g) => (
    <div key={g.title} className="guide-toc-group">
      <span className="eyebrow">{g.title}</span>
      {g.items.map(([id, title]) => (
        <button key={id} className={active === id ? "on" : ""} aria-current={active === id ? "location" : undefined} onClick={() => onPick(id)}>{title}</button>
      ))}
    </div>
  ));
}

export function GuidePage() {
  const [active, setActive] = useState("what");
  useEffect(() => {
    const on = () => {
      let cur = SECTIONS[0][0];
      for (const [id] of SECTIONS) {
        const el = document.getElementById(`guide-${id}`);
        if (el && el.getBoundingClientRect().top < 140) cur = id;
      }
      setActive(cur);
    };
    window.addEventListener("scroll", on, { passive: true });
    return () => window.removeEventListener("scroll", on);
  }, []);
  const [sheet, setSheet] = useState(false);
  const jump = (id: string) => { const el = document.getElementById(`guide-${id}`); if (el) scrollToStart(el); };
  const activeTitle = SECTIONS.find(([id]) => id === active)?.[1] ?? "";

  return (
    <div className="page guide">
      <nav className="guide-toc" aria-label="Contents">
        <Contents active={active} onPick={jump} />
      </nav>
      <div className="guide-contents-bar">
        <button type="button" className="btn guide-contents-btn" aria-haspopup="dialog" onClick={() => setSheet(true)}>
          <List size={16} /> Contents<span className="guide-contents-here">{activeTitle}</span>
        </button>
      </div>
      {sheet && (
        <Modal title="Contents" onClose={() => setSheet(false)}>
          <nav className="guide-toc guide-toc-sheet" aria-label="Contents">
            <Contents active={active} onPick={(id) => { setSheet(false); requestAnimationFrame(() => jump(id)); }} />
          </nav>
        </Modal>
      )}

      <article className="guide-body">
        <header className="guide-hero">
          <h1>How Process Manager works</h1>
          <p className="lead">One place for two questions. “How do I get a GCP project, a repository, an Akamai onboarding?” is answered by a <b>process</b>. “What must my application meet?” is answered by a <b>standard</b>. Both are written once, for people and for AI assistants.</p>
        </header>

        <Section id="what" title="What it is">
          <div className="guide-cards three">
            <div className="kind-process"><Workflow size={20} /><h3>Processes</h3><p>Who does what, in which order. Read as a map with one lane per participant, your lane first, or as your own checklist with the exact actions.</p></div>
            <div className="kind-standard"><ShieldCheck size={20} /><h3>Standards</h3><p>Rules set by cyber security, platform owners and practices. Each requirement says what must be true, why, how to comply and how it is checked.</p></div>
            <div className="kind-skill"><Bot size={20} /><h3>Skills for AI assistants</h3><p>From every process and standard the portal generates instructions an AI coding assistant can follow, and for standards a reviewer for pull requests.</p></div>
          </div>
          <p>Processes and standards share the same ground: an owning team, a category, a platform and a practice they can belong to, a life-cycle with regular reviews, feedback from readers, and the tiers, environments and languages they apply to.</p>
          <p><b>Getting around.</b> The top bar leads to every place: Home, Processes, Standards, Requests, My responsibilities (for the owners and members of a team, platform or practice), Teams &amp; tools (every team, platform and practice, each with a page of its own), the Guide and Admin (for those who configure). On a screen narrower than 1120 pixels, such as a tablet or a phone, the places are behind <b>Menu</b>, which shows, right after the word Menu, how much is waiting for you, like My responsibilities (“Menu, 2 waiting”), and then where you are; it opens a list of the places with their names. Escape, a press outside it or choosing a place closes it. The light and dark switch and your account menu always stay in the bar. With the keyboard, the first press of Tab shows <b>Skip to the page</b>, which goes past the top bar straight to the page itself (on the editing screen, to what readers will see).</p>
          <p><b>Dates and times</b> are written the same way everywhere: a day as year, month, day, such as “2026-11-13”, and a moment with its time, such as “2026-11-20 06:44”, in your own time zone. Only <b>Recently updated</b> on Home says “today” or “3 days ago” (point at it for the date). <b>Your day is the one on your own calendar</b>: “today” and “yesterday”, when a review is due or overdue, and the date a save or a review records are counted by the day where you are, not by the portal’s own clock, so they are right also late in the evening and early in the morning. A date written into a process or standard, such as when it was last reviewed, is shown as written, the same for everybody. Two places count whole days from midnight to midnight UTC instead, and say so: the views and the <b>Statistics</b> of the Admin panel; and AI agents asking over the MCP server, which have no calendar of their own, so a review can turn due for them a day earlier or later than for you.</p>
          <p><b>When the portal cannot be reached</b>, for example when your connection drops, a page that is loading says “Could not reach the portal. Check your connection and try again.”, and a change you tried to make says “Could not reach the portal. Nothing was saved. Check your connection and try again.”, so you know to repeat it. If a part of a page could not be fetched, the page says “This page could not be loaded” with “Could not reach the portal. Check your connection, then reload the page. Nothing you saved is lost.” and offers <b>Reload</b> and <b>Back to the start</b>; on any other fault it says “Something went wrong on this page”, with the same two buttons, and <b>Details</b> folds out what to pass on to support. A link to a process or standard that is gone says “This process does not exist (any more). It may have been renamed or deleted.” (or standard), with the way back to the list.</p>
          <p><b>This Guide</b> lists its sections on the left. On a narrow screen they are behind <b>Contents</b> at the top, which stays in view and names the section you are reading; and every section ends with <b>Back to top</b>.</p>
        </Section>

        <Section id="find" title="Finding a process or standard">
          <p><b>Home</b>, the first page and the first link in the top bar, is one search over processes and standards together. Type what you need, such as “GCP project” or “logging”, and press <b>Search</b> or Enter. By words, every word you type must be found somewhere in a process or standard; capitals and accents do not matter.</p>
          <p>Below the search box are the ways in without typing: <b>All processes</b> (“How to get something done”) and <b>All standards</b> (“The rules your work must meet”), each with how many there are; <b>Your bookmarks</b>, once you have some (the newest six, and <b>Show all</b> for the rest; they fill the width, so one bookmark is one wide card and two stand side by side); and two short lists, <b>Recently updated</b> (when, such as “3 days ago”) and <b>Most viewed</b> (with the number of views). These two show only published processes and standards in use, never a draft or a retired one, and count views, never people. Under them is the way to ask for what is missing. On the right, under <b>Browse</b> (below the rest on a narrow screen), are <b>By platform</b>, <b>By practice</b>, <b>By team</b> (“Everything a team owns”) and <b>By category</b>, each entry with the number of processes and standards it leads to in grey brackets after its name, such as “Google Cloud (5)”; a long group shows six and <b>Show all</b> for the rest. A platform, a practice or a team opens its own page (see <b>The page of a team, platform or practice</b>); a category opens the search with what is filed under it.</p>
          <p><b>Process or standard at a glance.</b> Where processes and standards are listed together, on Home, in the search results, your bookmarks, the requests and My responsibilities, each carries a tag with its kind: “Process” with a round sign, “Standard” with a square one, each in a colour of its own. The page of a process or standard has the same tag at the top. The Processes and Standards lists leave it out, since everything there is of one kind.</p>
          <p><b>By words or by meaning.</b> Where the portal has search by meaning switched on, the search results have a choice at the end of the search box (below it on a phone): <b>Words</b>, <b>Meaning</b> or <b>Both</b>. Point at a choice to see what it does; <b>How this works</b> next to it explains all three:</p>
          <dl className="guide-dl">
            <div><dt>Words</dt><dd>Finds what contains every word you type, as described above, and the results and the address follow as you type. Use it when you know a word that must be in it: a name, a tool, an id such as SEC-LOG-01.</dd></div>
            <div><dt>Meaning</dt><dd>Shows the closest first, even when not every word is in it. What it can do depends on how your portal is set up, and How this works says which applies. In some portals it “finds processes and standards about what you type, even when they use other words”: use it when you do not know the words the owners used, or to ask in a sentence, such as “where do I keep passwords for my service”. In others it “compares the words and parts of words you type with the text of every process and standard”, so that “logging” also finds “logs”; there it does not know that different words can mean the same thing, and it always shows the closest, even when none is really close. Either way it finds only what readers see: published processes and standards, never a draft and never unpublished changes. If you have drafts, the page reminds you that Words or Both find them too.</dd></div>
            <div><dt>Both</dt><dd>Shows what either finds, the best of each first; what both find rises. Each card says whether it was found by words, by meaning, or by both.</dd></div>
            <div><dt>When it searches</dt><dd>With Meaning and Both, the search is made when you press Enter or <b>Search</b>, when you change the choice, and when you arrive with a search, from Home or a link; not while you type, and the address changes only then. Until you press Enter, the results stay those of your earlier search, and a line says so: “These results are for the earlier search …”. When a process or standard was saved since, the next search asks again, so it finds the latest text.</dd></div>
            <div><dt>Closest by meaning</dt><dd>When you search by words and nothing contains all your words, the line above the results says “No exact match for “…”. Closest by meaning:” and the closest processes and standards follow, so you are not left with nothing; while they are being looked for, it says “No exact match for “…”.” and “Looking for the closest by meaning…”. It does this only for a search you made on purpose (Enter, Search, or a link); while you are still typing, the page offers <b>Show the closest by meaning</b> instead. When nothing comes close either, it says so, such as “Nothing matches “x”, and nothing comes close by meaning either. Try fewer or other words.”, and offers no button that would only repeat the search; when search by meaning cannot be reached, it says “The closest by meaning could not be looked for: search by meaning is not available right now.” The closest are looked for also when filters are chosen, and everything that narrows results narrows them too: the tabs All, Processes and Standards, the filters, <b>My application</b>, the chosen filters with their crosses, and Cards or Rows. Sort by, Per page and the page numbers are left out there, as the closest come in their own order, closest first. When the filters leave none of them, the page says so, such as “None of the 8 closest results by meaning matches these filters.”, with <b>Clear all filters</b>; when only the tab hides them, such as “None of the closest by meaning is a standard. All kinds together give 8 results.”, with <b>Show all kinds</b>.</dd></div>
            <div><dt>The same tools</dt><dd>The filters, the counts next to them, the order, the pages and “Found in” work the same with all three choices. “Found in” then names the step, the requirement, the prerequisite (“Before you start”), the scope or the summary that came closest. When more matched than the page was sent, it says so: “Showing the 500 closest. Add words or choose a filter to narrow it down.”, and the counts next to the filters read like “12+”, as there may be more.</dd></div>
            <div><dt>Your choice</dt><dd>Is remembered in this browser: the next search you start from Home is made the same way. The address holds it too, so a shared link searches the same way.</dd></div>
            <div><dt>When it does not work</dt><dd>If search by meaning is not available, or not ready yet (for a while after the portal was started or set up anew), the page says so and offers to search by words; with Both you see what words find in the meantime. If you search very often within a minute, it asks you to wait a moment. When Meaning finds nothing close, it offers to search by words, and the other way round.</dd></div>
            <div><dt>Where your words go</dt><dd>When the line under the search box says “With Meaning and Both, what you type is sent to Google Cloud to be compared.”, that is what happens: so type a question, not confidential details. Without that line, what you type stays in the portal. Words never sends anything anywhere.</dd></div>
          </dl>
          <p>The search results, <b>Processes</b> and <b>Standards</b> in the top bar all look the same: the filters on the left, the results on the right, in pages. The Processes list opens with “How do I get…?” and the Standards list with “What must I meet?”; their search box, across the top, searches as you type, such as “Search processes: GCP, repository, Akamai…” (on a phone just the examples, such as “e.g. GCP, repository, Akamai”). Whoever may create one finds <b>New process</b> (on the Standards list <b>New standard</b>) at the top, the main button, with <b>Create from text with AI</b> before it as the other choice. All three search inside as well, in the steps, requirements, prerequisites and scope. The words you searched for are marked in the results with a soft yellow, like a highlighter, which stays the same whatever the portal’s colours are; a word of one or two letters, such as “CI”, only where it stands on its own.</p>
          <dl className="guide-dl">
            <div><dt>All, Processes, Standards</dt><dd>On the search results, three tabs above the results show everything, only processes or only standards, each with how many results it gives.</dd></div>
            <div><dt><LayoutGrid size={14} />Cards or rows</dt><dd>Next to the number of results, <b>Cards</b> shows each result as a card; <b>Rows</b> shows one line each, in columns, to scan many at once: the kind as a small sign where kinds are mixed (point at it for the word), the name with its category under it (or where your words were found; point at a long name to read it whole), the marks for what needs attention, how binding it is, the lead time of a process or the number of requirements of a standard, the owner (left out on narrower screens) and, at the right, the bookmark and the other buttons. On a phone a row takes two lines. Your choice is remembered for every list, for you, in this browser. In such a switch of a few choices (also Words, Meaning and Both, and All, Must, Should, May on a standard) the chosen one is raised, with a fine outline and its text in the portal’s colour; the same goes for the current page number and the count on the chosen tab. A filled button in the portal’s colour is kept for the one main action of a page.</dd></div>
            <div><dt><Search size={14} />The order</dt><dd><b>Sort by</b>, next to the number of results, chooses it. <b>Best match</b> (when you searched for something) puts the best matches first: by words, a word in the name counts more than a word deep inside; by meaning, what comes closest. Without words to search for it is <b>Name</b>, in alphabetical order. <b>Newest</b> puts what was added last first, <b>Recently updated</b> what was published last. The order is part of the address; on the Processes and Standards lists it is also remembered for you in this browser.</dd></div>
            <div><dt>Filters</dt><dd>On the left. Under <b>Show only</b>: <b>Only my bookmarks</b> shows what you bookmarked (until your bookmarks have been loaded it cannot be ticked, and says why); when something you look after is due for a review, <b>Only what needs a review</b> is offered as well and shows just that. Under <b>Narrow down</b>, each a list that opens when you press it and shows what is chosen, or “Any”: <b>Category</b>, <b>Platform</b>, <b>Practice</b>, how binding it is (<b>Rigour</b>, on every list) and <b>Owner</b> (the owning team). Tick several values of one filter to see what matches any of them; filters of different kinds must all match. Every value shows how many results it would give; values that give nothing are greyed out or left out. Processes and standards without a category are under <b>Other</b>, at the end.</dd></div>
            <div><dt>Levels in words</dt><dd>A process says itself how binding it is: <b>Mandatory</b> (the only allowed way), <b>Recommended</b> or <b>Optional</b>. A requirement of a standard is <b>Must</b>, <b>Should</b> or <b>May</b>, and a standard is as binding as its requirements: it is found under every level it has at least one requirement of. So the Rigour filter offers Mandatory, Recommended, Optional on the Processes list; Must, Should, May on the Standards list; and “Mandatory or must”, “Recommended or should”, “Optional or may” on the search results. Everywhere a level is shown as three bars, three filled for mandatory or must, two for recommended or should, one for optional or may, always with the word. A process that does not say how binding it is shows “Rigour not stated” with three empty bars, so that every card has the same lines. A level is a fact, not a problem, so it is never shown in the colour of problems.</dd></div>
            <div><dt>My application</dt><dd>Folded under the other filters, with what you chose or “Not chosen”: choose one <b>Tier</b>, one <b>Environment</b> and one <b>Language</b> (or “Any”), and what does not apply to such an application is hidden, “here and on every process and standard”. They always offer every tier, environment and language in the lists with how many results it would give, also when that is 0: you can still choose it, as it describes your application, and the page then says that nothing matches. Your choice is remembered in this browser, for every list and every standard; the group opens by itself while something is chosen.</dd></div>
            <div><dt>Nothing to choose</dt><dd>When no value of one of the other filters would give a result, the filter says “Nothing to choose” and, when you open it, why: for example “No process here says how binding it is.” or “Nothing matches the other choices, so there is nothing to choose here.”</dd></div>
            <div><dt>The chosen filters</dt><dd>Listed above the results, each with a cross to remove it; <b>Clear all filters</b> removes them all. On a narrow screen the filters are folded away: the <b>Filters</b> button opens them and says how many are chosen, Sort by and Per page are inside it, the chosen filters are one line that scrolls sideways, and a button at the end of the filters, such as “Show 12 processes”, closes them and goes to the results.</dd></div>
            <div><dt>Pages</dt><dd>One line above the results says how many there are and which are shown, such as “Showing 13–24 of 57 processes”, followed by Sort by, <b>Per page</b> (12, 24 or 48) and the page numbers. Under the results are the page numbers again and a second Per page, so you do not have to scroll back up. The number per page is remembered in your browser for every list. A new search or filter starts again on the first page; Back, or reloading the page, returns to the page you were on.</dd></div>
            <div><dt>Share a search</dt><dd>The address in your browser holds the whole search, on the search results and on the Processes and Standards lists alike: the words, by words or by meaning, every filter, the order, the page and how many are on it. Copy it to send a colleague exactly these results; reload it, or open a result and press Back, and you are back at the same results. Three choices are about you and are not in it: Only my bookmarks and Only what needs a review, which stay on in this browser tab until you turn them off, and My application. When a link names a filter that no longer exists, such as a platform removed from the lists since, that filter is left out, the address is corrected, and the page says “A filter in this link no longer exists and was left out.”</dd></div>
            <div><dt>Nothing found</dt><dd>The page says so and why, such as “Nothing matches “x”. Every word must be found, so try fewer words.”; where search by meaning is on, it shows the closest by meaning instead, as described above. It shows no filters, tabs, order or pages then, as there is nothing to narrow down. With filters chosen, only the chosen filters stay above the results, each with its cross to remove it. When the filters are what hides the results, the page says how many there are without them, such as “Nothing matches “x” with these filters. Without them there are 4 results.”, and offers one button, <b>Clear all filters</b>; when nothing matches either way, it says “Nothing matches “x”, with or without these filters.” The Processes and Standards lists say “No process matches.” (or standard), with the same one <b>Clear all filters</b>. It also points to all processes and all standards, and to <b>Requests</b>, to ask for what is missing.</dd></div>
            <div><dt>Drafts and retired ones</dt><dd>A process or standard that was never published is found only by the people who may see its drafts (see <b>Drafts and publishing</b>), marked “Draft” on a dashed card. Changes to a published one that are not published yet are never found: everybody finds the published version, and the people who may work on its drafts see “Unpublished changes” on the card. Retired processes and standards are found and marked as retired, their card or row greyed out.</dd></div>
          </dl>
          <p>A <b>card</b> shows one process or standard. At the top: its kind (where kinds are mixed), its category, and in the right-hand corner the application tiers it applies to, on one line (“All tiers” when it is not limited; a long list is counted, such as “3 tiers”: point at it for the whole list). Then its name, which opens it, and two lines of its summary; in a row of cards the names start at the same height, so they are easy to scan. Then one line of facts to compare: how binding it is (for a standard, such as “5 requirements · 4 must · 1 should”, or how many of them apply to your application when you chose one), for a process its lead time, how many of its steps are yours (“5 of 10 steps are yours”) and how many processes use it as a sub-process. Then a line of who looks after it and where it applies: the owning team, platform and practice, and the environments and languages when it is limited to some, each with a small icon; point at one to read what it is.</p>
          <p>When your words were found inside, up to two places are listed, each opening the process or standard right at that step or requirement, and “2 more places” when there are more; a requirement shows its name, then its code in small grey letters, such as SEC-SCR-05. Just above the bottom line are the marks for what needs attention, for the people they concern: “Draft”, “Retired”, “Unpublished changes”, “Needs fixing” (what is stored has something to fix; it leads to the editing screen), and for the people who look after it “Review due …” or “First review due …” in amber, or “Review overdue since …” in red. At the bottom: the open feedback, such as “2 open feedback”, which opens its Feedback tab; a button to give feedback; the upvote with how many people found it useful; and the bookmark (see <b>Bookmarks, upvotes and sharing</b>). The upvote and the bookmark appear once the numbers have been loaded.</p>
        </Section>

        <Section id="modes" title="Signing in and your rights">
          <p>You sign in with your company account, through Entra ID or Google depending on how the app was set up. The app never sees your password; it only learns your name and email.</p>
          <ProcessPicture className="guide-fig" process={signInFlow} caption="Signing in. Your rights are looked up on every request, so a change to them applies at once." />
          <p>Everyone who can sign in can read everything that is published, tick steps, give feedback, bookmark, upvote and share, and ask for a process or standard that is missing. A <b>role</b> adds more. Roles are given by an admin in the Admin panel; open your account menu (top right) to see yours, one per line in the same words as Admin › Access, saying of what, such as “Owner for Cloud Platform team”. Somebody without a role is shown there as “Reader”.</p>
          <table className="guide-table roles">
            <thead><tr><th>Role</th><th>Adds</th><th>Limited to</th></tr></thead>
            <tbody>
              <tr><td><b>Owner</b></td><td>Confirm reviews; mark feedback as fixed, reopen or delete it; open drafts that were never published; change the team’s description and how to reach it. Does not change the content.</td><td>What one team maintains</td></tr>
              <tr><td><b>Platform owner</b></td><td>Edit, publish, retire and delete processes and standards, and create new ones; publish what the platform’s members wrote; confirm their reviews; close their feedback; open their drafts; plan, answer or decline the requests that name the platform; add and remove the platform’s members and change its description and how to reach it. Sets a platform or practice only from one of their own to another</td><td>What belongs to one platform</td></tr>
              <tr><td><b>Practice owner</b></td><td>The same as a Platform owner, for what belongs to one practice and for the practice’s members and details</td><td>What belongs to one practice</td></tr>
              <tr><td><b>Platform member</b></td><td>Create drafts of processes and standards there, and save and discard changes to what belongs to the platform, for an owner to publish; open its drafts. Does not publish, retire, unpublish or delete, confirm reviews or answer feedback</td><td>What belongs to one platform</td></tr>
              <tr><td><b>Practice member</b></td><td>The same as a Platform member, for what belongs to one practice</td><td>What belongs to one practice</td></tr>
              <tr><td><b>Process editor</b></td><td>Edit, publish, retire and delete processes, and create new ones; close their feedback; plan, answer or decline requests for processes</td><td>All processes</td></tr>
              <tr><td><b>Standards editor</b></td><td>Edit, publish, retire and delete standards, and create new ones; close their feedback; plan, answer or decline requests for standards</td><td>All standards</td></tr>
              <tr><td><b>Lists manager</b></td><td>Teams, practices, platforms, categories, tools (with their icons), tiers, environments and languages</td><td>—</td></tr>
              <tr><td><b>Admin</b></td><td>Everything, including who has which role, the activity log and the statistics</td><td>—</td></tr>
            </tbody>
          </table>
          <p>One person can have several roles at once, for example be an ordinary reader everywhere, Platform owner of one platform and Practice member of one practice; where two roles meet, the stronger wins. Owner, Platform owner and Practice owner make you an <b>owner</b> of a team, platform or practice; Platform member and Practice member make you a <b>member</b> of a platform or practice. <b>Teams, platforms and practices</b> below explains what that means and how to see who they are.</p>
          <p><b>Signing out</b> ends your session everywhere, not only in this browser. A session also ends by itself after some hours. If that happens while a page is open, the page stays as it is, with anything you were editing, and asks you to sign in again in another tab.</p>
          <p>Everyone sees the same pages. There is no separate mode for editing: what you may do decides which buttons you get. Whoever may change a process or standard, or write drafts of it, finds <b>Edit</b> on its page, which opens the editing screen (see <b>The editing screen</b>); whoever looks after it also finds <b>Mark as reviewed</b>. The server checks the same rights on every change, so a hidden button is never the only protection.</p>
          <div className="guide-cards two">
            <div className="mode-card">
              <h3><Eye size={18} />Everyone</h3>
              <p>For people who need something done or need to know the rules.</p>
              <ul>
                <li><Check size={14} />Search processes and standards together; filter by category, platform, practice, how binding it is, owner and your application</li>
                <li><Check size={14} />Read the map, follow the checklist, read the requirements</li>
                <li><Check size={14} />Tick prerequisites and steps (kept in your browser)</li>
                <li><Check size={14} />Flag what does not work, or say “I hit this too”</li>
                <li><Check size={14} />Bookmark, upvote and share; ask for what is missing</li>
                <li><Check size={14} />See every published version and what changed</li>
                <li><Check size={14} />Read and download the generated skills</li>
              </ul>
            </div>
            <div className="mode-card editor">
              <h3><Pencil size={18} />Whoever may change it</h3>
              <p>Editors, business analysts and the owners and members of platforms and practices, for what their role covers. Everything above, plus:</p>
              <ul>
                <li><Check size={14} />Create processes and standards, from scratch or from text with AI</li>
                <li><Check size={14} />Edit on a screen of its own: the map or the requirements, and every field</li>
                <li><Check size={14} />Save drafts that readers do not see, then publish (a member leaves publishing to an owner)</li>
                <li><Check size={14} />Undo, and bring back any earlier version</li>
                <li><Check size={14} />Retire, unpublish or delete (not members)</li>
                <li><Check size={14} />Extra guidance for the generated skills (not members)</li>
              </ul>
            </div>
          </div>
        </Section>

        <Section id="belong" title="Teams, platforms and practices">
          <p>Every process and standard has an <b>owning team</b>, and can also belong to a <b>platform</b> and a <b>practice</b> and be filed under a <b>category</b>. Each answers a different question:</p>
          <dl className="guide-dl">
            <div><dt><Users size={14} />Owning team</dt><dd>Who maintains it. The Owners of the team confirm its reviews and answer its feedback; they do not change the content themselves. Any team can own a process or issue a standard.</dd></div>
            <div><dt><Boxes size={14} />Platform</dt><dd>What it is about: something people build on or get access to, such as Google Cloud, Apigee or GitHub. The owners of the platform may change and publish it; its members may write drafts of it for an owner to publish.</dd></div>
            <div><dt><Compass size={14} />Practice</dt><dd>The discipline that looks after it, such as cyber security or engineering. The owners of the practice may change and publish it; its members may write drafts of it for an owner to publish.</dd></div>
            <div><dt><Tag size={14} />Category</dt><dd>The subject it is filed under, such as Cloud or Network. It helps readers find it and gives nobody any rights.</dd></div>
          </dl>
          <p><b>Owners and members.</b> A team has <b>owners</b> (the role Owner). A platform and a practice have <b>owners</b> (Platform owner, Practice owner) and can have <b>members</b> (Platform member, Practice member). A person can belong to a team, a platform and a practice at the same time, and to several of each. Owners are given and taken by an admin only. The members of a platform or practice are added and removed by an admin or by an owner of that same platform or practice, on its page. Everyone can see who they are: open <b>Teams &amp; tools</b> in the top bar, choose Teams, Platforms or Practices, and pick one, or open its page (see <b>The page of a team, platform or practice</b>). That is how you find out who publishes what belongs to a platform or practice, who writes its drafts, or whom to ask about a review.</p>
          <ProcessPicture className="guide-fig" process={rightsFlow} caption="Who may do what with one process or standard. Everybody who can sign in may read it and give feedback." />
          <dl className="guide-dl">
            <div><dt>May change and publish it</dt><dd>Edit and publish it, see and continue its unpublished changes, retire, unpublish, bring back or delete it, bring back an earlier version, and create new ones: admins, process editors for every process, standards editors for every standard, and the owners of the platform or the practice it belongs to.</dd></div>
            <div><dt>May write drafts of it</dt><dd>Create new ones on the platform or in the practice, open it on the editing screen, change it there and press Save draft, and discard those drafts: everyone who may change it, and the members of its platform or practice. A member never publishes: <b>Publish…</b> is not available to them, and the editing screen names who publishes (see <b>Drafts and publishing</b>). Members do not retire, unpublish, bring back or delete, confirm reviews, answer feedback, move requests along or add guidance to skills. A member cannot mark a draft as ready for the owner: the owner finds it under <b>My responsibilities</b>, in “Waiting for you to publish”.</dd></div>
            <div><dt>May look after it</dt><dd>Confirm reviews and answer feedback: everyone who may change it, and the Owners of its owning team.</dd></div>
            <div><dt>Who sees a draft</dt><dd>A process that was never published is seen only by the process editors, the owners and members of its platform or practice, and the Owners of its team (for a standard, the standards editors instead of the process editors); for everyone else it does not exist. Unpublished changes to something published are seen only by the people who may write drafts of it, not by the Owners of its team.</dd></div>
            <div><dt>The first publication</dt><dd>Publishing something for the first time needs the right for everything it is placed on: an owner of every platform and practice it names, or an editor of its kind. A process on the platform Google Cloud and in the practice Cyber security is first published by somebody who owns both, or by a process editor; to anyone else Publish… looks unavailable and a line on the editing screen says who publishes: “Somebody who owns both Google Cloud and Cyber security publishes this: Ann Lee. Your draft is saved for them.”, or “Nobody owns both Google Cloud and Cyber security yet: a process editor publishes this. Your draft is saved for them.” Once it is published, an owner of either may publish changes to it, as long as its platform and practice stay as they are; changing them needs an owner of where it was and of where it goes.</dd></div>
            <div><dt>Staying within your own</dt><dd>A platform or practice owner changes only what belongs to their platforms and practices, and a member writes drafts only there. They cannot take over a process or standard of another platform, nor move one of theirs to a platform and practice that are not theirs: the editing screen warns about it under About, Save draft and Publish say why they cannot be used, and the server refuses such a save. When they create something new, they choose which of their platforms or practices it belongs to; for a place where they are only a member the choice says “An owner of the platform or practice publishes it.”</dd></div>
            <div><dt>A platform that is not yours</dt><dd>A platform or practice owner or member may set or change the platform of a process or standard only from one of their own platforms to another, or to or from none. A platform that is not theirs stays as it is: under About on the editing screen its picker is locked, with “Only its owners and members, or an editor, can change this”, and the server refuses such a save. The same goes, separately, for the practice. Everything else they may change, the owning team included. Admins and editors are not limited this way.</dd></div>
          </dl>
        </Section>

        <Section id="group" title="The page of a team, platform or practice">
          <p>Every team, platform and practice has a page of its own, for everyone who signs in. Open it from <b>Teams &amp; tools</b> (<b>Open the page of …</b>), from <b>Browse</b> on Home, or by its name in the head of a process or standard: the owning team, the platform and the practice there are links. Its address is <code>#/team/…</code>, <code>#/platform/…</code> or <code>#/practice/…</code> with the id of the entry; a page for something no longer in the lists says “This platform does not exist (any more). It may have been removed from the lists.” with <b>Back to Teams &amp; tools</b>.</p>
          <dl className="guide-dl">
            <div><dt>The head</dt><dd><b>Teams &amp; tools</b>, the way back to the entry in the list; the kind, such as “Platform”, and, if you are one of its people, “You are an owner” or “You are a member”; the name; and what it is, or “No description yet.”</dd></div>
            <div><dt>How to reach them</dt><dd>The <b>Request form</b>, where people ask them for something, is the one main button, <b>Open the request form</b>, and opens in a new tab. Under it, each only when it is known: the <b>Group email</b> (a mail link), the <b>Slack channel</b> and the <b>Google Chat space</b> (a link when the link is known, else the name), the <b>Confluence page</b> and <b>Their page</b>, and <b>Other ways to reach them</b>, a free line, left out when it only repeats a detail above. When nothing is known it says “Nothing is known yet about how to reach them.” Only links that start with http:// or https:// are shown as links.</dd></div>
            <div><dt>Owners and members</dt><dd><b>Owners</b>, and for a platform or practice <b>Members</b> when it has any, each by name where the portal knows it, else by email; a name is a mail link, with the email when you point at it, and you are marked “You”. A line says what they do: “Owners decide what is published here.” (for a team “Owners review what this team looks after and answer its feedback.”) and “Members write drafts for the owners.”; an admin and the group’s own owners and members read it at more length. A group without owners says “No owner yet. Use the ways to reach them above.”</dd></div>
            <div><dt>What belongs to it</dt><dd>“What belongs to this platform” (or practice), for a team “What this team looks after”: its processes and standards as cards or rows, as in the lists, with how many of each, such as “2 processes and 1 standard”; the first 12, then <b>Show all</b>. <b>Open in the search</b> opens the same as a search with its filter. Drafts are shown only to the people who may see them. Whoever may create one there finds <b>New process</b> and <b>New standard</b>, which start on this platform or practice (from a team’s page, owned by that team); the dialog says so, such as “It belongs to the platform “Google Cloud”. You can change that later.”</dd></div>
            <div><dt>Edit details</dt><dd>Admins, lists managers and the group’s owners (a team’s Owners for a team) change its description and how to reach it with <b>Edit details</b>: the description (“What they do” for a team, “What it is” for a platform, “What it covers” for a practice, up to 600 characters), Group email, Slack channel and its link, Google Chat space and its link, Confluence page, Their page, Request form and Other ways to reach them. Leave out what does not apply. A link typed without its beginning gets https:// when you leave the field; a field with a problem is marked and says what to do, such as “Write the whole link, starting with https://” or “Write one email address, like team@company.com.”, and Save then says “Fix the marked fields first.” Cancel with changes asks “Discard your changes?”. After saving: “The details of Google Cloud are saved.” The name and the id are changed only in <b>Admin › Lists</b>. Every change is a new version of the lists and is in <b>Admin › Activity</b>, naming what changed.</dd></div>
            <div><dt>Adding and removing members</dt><dd>An admin or an owner of the platform or practice types an email address under Members and presses <b>Add member</b> (or Enter): “Sam Consumer can now create and change drafts for Google Cloud.”, with <b>Undo</b>. When nobody with that address has done anything in the portal yet, a line says so, so you can check it is right; the person is added all the same. The bin next to a member removes them after a question: “… will no longer be a Platform member of Google Cloud and will no longer be able to create or change its drafts. Their drafts stay.” Owners are given and taken only by an admin, here under Owners (<b>Add owner</b>) or in Admin › Access.</dd></div>
            <div><dt>Printing and the phone</dt><dd>From 1000 pixels wide, what belongs to it is on the left and how to reach them and the people on the right; on a narrower screen they follow one another. Printed, the page leaves out the buttons and prints the addresses of the links.</dd></div>
          </dl>
        </Section>

        <Section id="read" title="Reading a process">
          <p>Open a process from a search, from <b>Processes</b> in the top bar or from a bookmark. The header reads like its card, with more room:</p>
          <dl className="guide-dl">
            <div><dt>Above the name</dt><dd><b>All processes</b>, the way back to the list; the “Process” tag, its category and “Owned by” its team, whose name opens the team’s page; and marks for what needs attention: “Draft”, “Retired”, and for the people who look after it “First review due …” or “Review due …” in amber, “Review overdue since …” in red.</dd></div>
            <div><dt>The facts</dt><dd>One line under the summary: how binding it is (Mandatory, Recommended or Optional, with its bars; point at it for what that means), the typical time, how many of its steps are yours, such as “5 of 10 steps are yours”, and how many others take part; then the platform and practice it belongs to (each name opens its page) and which <b>application tiers</b>, <b>environments</b> and <b>programming languages</b> it applies to. Use Tier, Environment and Language in the filters of the list to hide what does not apply to you; your choice is remembered.</dd></div>
            <div><dt>A quiet line</dt><dd>“Content changed …”, when what it says last changed (point at it: the list of versions shows every time it was stored, also when it was imported or confirmed in a review); “Reviewed …” with the date of the last review, or “First review due …” while its first review is not near yet, or else “Not reviewed yet” (a review that is due or overdue is already a mark at the top, with its date); and the <b>version</b>: press it to see who changed what and when, by name.</dd></div>
          </dl>
          <p>If you may change the process, or write drafts of it as a member of its platform or practice, the header has <b>Edit</b>, its main button, which opens the editing screen; if you look after it, <b>Mark as reviewed</b> (see <b>Life-cycle and reviews</b>), a quiet button until a review is due or overdue, when it is marked in amber. Nothing else on the page changes the process.</p>
          <p>What a reader must know first stands right under the name and summary, before the facts: “This process is retired.”, with what to use instead or “It is kept for reference only.”; and, for the people who look after it, that its review is overdue, with what to do: read it through (correct what changed on the editing screen, if you may), then press “Mark as reviewed”.</p>
          <p>For the people who may write drafts of it, a line under the header says when there are <b>unpublished changes</b>, by whom and from when, such as “You have unpublished changes (saved 2026-11-20 14:02). Readers see the published version.” or “There are unpublished changes by Alex Editor, saved 2026-11-20 09:15. …”, with <b>Continue editing</b>: the page itself always shows what readers see. A member, who does not publish, reads who does: “You have unpublished changes (saved …). An owner of Google Cloud publishes them; readers see the published version until then.” A process that was never published says “Draft · Readers do not see this process yet. Only the process editors, the owners and members of its platform or practice, and the Owners of its team can open it.”; when its editing screen holds newer changes that still have something to fix, the people who may write drafts of it also read, for example, “There are newer changes on the editing screen by Dana Admin, saved 2026-11-20 10:29.”, with Continue editing.</p>
          <p>Below the quiet line, the header says how much the process is used, as short as it can be: “200 views by 36 people” (or “No views yet”), “4 skill downloads”, “1 piece of feedback open” and “3 pieces of feedback handled”. A number that is zero is left out, apart from the views. Your own visit counts at once. While the numbers are loading the line shows a dash; if they cannot be loaded it says “The numbers are not available right now.” rather than showing zeros. What you can do with it, <b>Give feedback</b> (a plain button like the others), the upvote, the bookmark and <b>Share</b> (see <b>Bookmarks, upvotes and sharing</b>), sits at the right end of the row of tabs on a screen 1000 pixels wide or more, where the upvote, the bookmark and Share show only their icons below 1200 pixels or while a step is open beside the map; on a narrower screen they are in the header, and on a phone the last three show only their icons, to keep them on one line. Below:</p>
          <dl className="guide-dl">
            <div><dt>How binding it is</dt><dd><b>Mandatory</b>: the only allowed way to get this done. <b>Recommended</b>: the expected way; another way needs a good reason. <b>Optional</b>: a help that may be used, or not. Some processes do not say.</dd></div>
            <div><dt>The tabs</dt><dd><b>Map</b>, <b>Checklist</b>, <b>Feedback</b> (with the number of open items) and <b>Skills</b>, under the header. A link decides which tab a process opens on, the Map when it names none. On a phone, a process that would open on its map without a step named opens on its <b>Checklist</b> instead, which reads better on a small screen; pressing Map afterwards shows the map.</dd></div>
            <div><dt>Before you start</dt><dd>One compact panel above the map and above the checklist alike. Its first line has <b>Before you start</b> with how many of the prerequisites you have ready, such as “1/3 ready”, and next to it the links that help: <b>Do it faster</b> (self-service skills first, then repositories, templates, documentation and other links) and <b>Helps to meet</b> (the standards the process helps to meet), always in view, also when the panel is folded. Below are the prerequisites, in one row of short items: tick what you already have; point at one to read all of it; if a prerequisite is itself a process, a link takes you there. The panel is open when you arrive; press its first line to fold it away, and it stays folded the next time in this browser. A process that needs nothing beforehand has only the line with the links, with nothing to fold.</dd></div>
            <div><dt>Map</dt><dd>Time runs left to right, each lane is one participant. A <b>decision</b> is drawn as a diamond, with a name on each path out of it. Dashed arrows loop back, for example after a rejection. <b>Select a step</b> to open on the right what to do and who does it; a line under its name says where it is done (the tool, with its icon and, when the tool has an address, a link that opens it in a new tab) and how long it takes. Until you have opened a step once, a hint next to the tabs says “Select a step for what to do” (“Tap a step …” on a touch screen); it is hidden while a step is open. The map moves the selected step to its middle (the page itself does not scroll), so that you also see where it leads; when the step’s panel opens beside the map and makes it narrower, the step is brought back to the middle. Above the map is the legend of the kinds of steps it uses; on a phone it is behind a <b>Legend</b> button, to leave the room to the map. The names of the participants are a column of their own on the left, which stays in place while the map moves; it gets narrower when you zoom out, and its text keeps its size. A long name breaks between words and is never cut inside a word: it ends with “…” after the last whole word that fits, or shows only its first letter when not even its first word fits; point at a name to read it whole, with how many steps the participant has, such as “Requester: 4 steps”.</dd></div>
            <div><dt><Hand size={14} />Moving around</dt><dd>A map is often bigger than the screen. Drag it with the mouse to move around; a short click still opens a step. On a touch screen, swipe, and pinch to zoom; the line above the map then says “Swipe to move · pinch to zoom”. The map opens at its start, as large as lets the whole flow fit either the width or the height of the map, whichever gives the larger size, but never above 100% and never below 60%, so that the names of the steps stay readable; a long flow then uses the height and scrolls sideways, and a soft fade on the left or right edge shows that it goes on that way. The size is chosen once, when the map opens: folding “Before you start” does not change it. To zoom, use the tools above the map, on the right: <b>Fit</b> (“Show the whole flow”) shows the whole flow at whatever size that takes, from its start, and scrolls the page so that the whole map is on the screen. Fit is an overview: as soon as you select a step, the map goes back to the size it opened at, with that step in the middle; zooming with minus or plus after Fit goes on from the size Fit chose. The minus and plus zoom out (down to 40%, or to the size of Fit when that is smaller) and in, and the percentage between them goes back to 100%. Or hold Ctrl (⌘ on a Mac) and scroll with the pointer over the map, or pinch on a trackpad: the map zooms around the pointer. A plain scroll keeps scrolling the page. The line above the map reminds you: “Drag to move · Ctrl + scroll to zoom”. The flow charts in this guide and in the code map move the same way: drag one, zoom it with its own tools or Ctrl + scroll, <b>Fit</b> shows the whole chart, and <b>Enlarge</b> opens it as large as the window; a chart opens whole when it is still readable that way, otherwise at 80% with a fade on the edge where it goes on. A plain scroll over a chart keeps scrolling the page.</dd></div>
            <div><dt>With the keyboard</dt><dd>The steps of the map are one stop for the Tab key, so Tab does not walk through every block: it lands on the selected step (or the first), the arrow keys move from step to step in the order of their numbers, Home and End go to the first and the last, and Enter opens the step. The map moves with the focus, so the step you are on is always fully in view, marked by a ring in the portal’s colour. Each block is read out with its number, name, kind and participant, such as “3. Approve the budget, Approve, by Manager”.</dd></div>
            <div><dt><Flag size={14} />Report a problem with a step</dt><dd>Point at a step, or move to it with the keyboard (its flag is the next Tab stop after it), and a small flag appears in its corner (on a touch screen it is always there). Press it to tell the owner what is wrong with that step, without opening the step first. A red flag with a number shows how much feedback on the step is still open.</dd></div>
            <div><dt>Checklist</dt><dd>Steps in order. Yours show the exact actions, the link to open and what you get at the end. Steps of others are collapsed so you know what you are waiting for. A bar says how many of your steps are done; <b>Only my steps</b> hides the others and <b>Reset ticks</b> clears your ticks. On a wide screen this bar is a column beside the steps that stays in view while you scroll.</dd></div>
            <div><dt>A link to one step</dt><dd>Opening a step changes the address in your browser. Copy it to send someone straight to that step. The Back button closes the step again. <b>Share</b> always gives the address of the whole process.</dd></div>
            <div><dt>Sub-processes</dt><dd>A step can hand over to another process, such as “Raise a ServiceNow request”. Expand it in place or open it.</dd></div>
            <div><dt>Printing</dt><dd>Print the page with your browser (Ctrl+P, ⌘P on a Mac) for a paper copy on A4, always in the light look, whatever tab is open: the header, “Before you start” with the full texts and addresses of its links, then the checklist with every step, who does it, all its instructions and its tool. Buttons, menus and the top bar are left out. The last line says which process and version it is, when its content last changed and when and from where it was printed, such as “Request a GCP project · Version 1 · content changed 2026-11-13 · printed 2026-11-20 10:18 from …”, so a paper copy can be told apart from a newer one.</dd></div>
          </dl>
        </Section>

        <Section id="follow" title="Following a process">
          <p>The typical path of a reader, from finding the process to getting the result.</p>
          <ProcessPicture className="guide-fig" process={followFlow} caption="A reader following a process. The dashed loop is a missing prerequisite. If a step fails, flagging it tells the owner." />
        </Section>

        <Section id="blocks" title="The building blocks">
          <p>Every step has a kind. The kind sets the icon and colour, so the map can be read without reading every title. A decision has no icon on the map: it is the diamond.</p>
          <div className="guide-blocks">
            {STEP_TYPES.map((t) => (
              <div key={t}><TypeIcon type={t} size={34} /><div><strong>{STEP_META[t].label}</strong><span>{STEP_META[t].when}</span></div></div>
            ))}
          </div>
        </Section>

        <Section id="standards" title="Reading a standard">
          <p>A standard is a list of requirements, such as the rules of cyber security, of a platform or of a practice. It is issued by a team, which reviews it and answers its feedback. Open one from a search, from <b>Standards</b> in the top bar or from a bookmark. The page has the same frame as a process, with the name in the same place, and its header is built the same way: <b>All standards</b>, the “Standard” tag, its category and “Issued by” its team (the names of the team, platform and practice open their pages), the same marks (draft, retired, review), the name, then on one line how many requirements it has and of which level, such as “5 requirements · 4 must · 1 should”, and where it applies, and the quiet line with when its content changed, the review (“Reviewed …”, “First review due …” or “Not reviewed yet”) and the version. Its tabs are <b>Requirements</b>, <b>Feedback</b> and <b>Skills</b>. At the end of the header, the same numbers as on a process (views and people, skill downloads, open and handled feedback, each left out while it is zero), with <b>Give feedback</b>, the upvote, the bookmark and <b>Share</b>, which sit on the row of tabs on a wide screen, as on a process. As on a process, <b>Edit</b> (the main button), <b>Mark as reviewed</b> (quiet unless a review is due) and the line about unpublished changes appear only for the people they concern, and the notice that it is retired (for everyone) or that its review is overdue (for those who look after it) stands under the name and summary. Below the header, one band, “About this standard”, holds its scope, how to ask for an exception, the processes that help and the background reading side by side; then come the requirements, as wide as the page of a process. On a screen 1100 pixels wide or more each requirement has the rule, why and how to comply on the left and its examples on the right.</p>
          <dl className="guide-dl">
            <div><dt>Must, should, may</dt><dd><b>Must</b> is mandatory; deviating needs an exception from the team that issues the standard. <b>Should</b> is expected unless you have a good reason. <b>May</b> is optional good practice. Each requirement shows its level as three, two or one bars with the word, in the same plain colour for all three. Above the list, <b>All</b>, <b>Must</b>, <b>Should</b> and <b>May</b>, each with its count, show only the requirements of one level. A standard has no level of its own: in search it is found under each level its requirements have.</dd></div>
            <div><dt>Each requirement</dt><dd>Its name, followed by the id people and tools cite (such as SEC-LOG-01) in small grey letters, then the rule in a sentence, why it exists, how to comply, good and bad examples, and how it is checked: automatically, in code review, or by a person.</dd></div>
            <div><dt>My application</dt><dd>Choose your tier, environment and language. Requirements that do not apply to you are folded away, and the counts follow. It is the same choice as Tier, Environment and Language in the filters of the lists, remembered for every list and every standard.</dd></div>
            <div><dt>A link to one requirement</dt><dd>Opening a requirement changes the address in your browser. Copy it to point someone at exactly that rule.</dd></div>
            <div><dt>What reviewers look for</dt><dd>The concrete signs of a violation in a pull request. The review agent generated from the standard checks exactly these.</dd></div>
            <div><dt>Exceptions and help</dt><dd>The band at the top says how to ask for an exception and lists the processes that help you comply; links to a process are in the colour of processes, links to a standard in the colour of standards, here and on every page.</dd></div>
            <div><dt>Printing</dt><dd>Printed (Ctrl+P, ⌘P on a Mac), a standard gives its header, the scope, exceptions, processes that help and background, and every requirement, whatever level or application you chose on the screen, on A4 in the light look; the last line says which standard and version it is, when its content last changed and when and from where it was printed.</dd></div>
          </dl>
        </Section>

        <Section id="feedback" title="Feedback">
          <p>When a step does not work or a requirement is wrong or unclear, say so where you are: the <Flag size={13} /> flag on the step on the map, in the checklist or on the requirement, <b>Report a problem</b> in the panel of an open step or requirement, or <b>Give feedback</b> for the whole process or standard, on its page or on its card in a list. Pick a kind (doesn’t work, out of date, unclear, suggestion), write a sentence, send. Your name comes from your sign-in.</p>
          <p><b>Give feedback</b> opens the <b>Feedback</b> tab with the cursor in the form; there you can also choose the step or requirement it is about. Under the form is all feedback given so far, with how much is open and how much was handled: the open items first, the ones most people hit first.</p>
          <ProcessPicture className="guide-fig" process={feedbackFlow} caption="A reported problem stays visible on the step until the owner marks it as fixed. Standards work the same way, per requirement." />
          <dl className="guide-dl">
            <div><dt>Open and handled</dt><dd>Feedback is open until somebody who looks after the process or standard marks it as fixed; then it counts as handled. Both numbers are shown in the header of every process and standard once there is any, so you can see whether feedback there gets answered. A card in a list shows the open feedback at its bottom, such as “2 open feedback”, which opens the Feedback tab.</dd></div>
            <div><dt>I hit this too</dt><dd>If someone already reported your problem, add yourself with one click. The count tells the owner what to fix first.</dd></div>
            <div><dt>Who can close it</dt><dd>Whoever may change the process or standard, and the Owners of the team that owns it; the members of its platform or practice do not. The reporter is told when it is marked as fixed. Marked as fixed by mistake? <b>Reopen</b> it.</dd></div>
            <div><dt>May already be fixed</dt><dd>When a step or requirement is changed after feedback was written about it, the feedback says so. Owners can then close old items quickly.</dd></div>
            <div><dt>On a draft</dt><dd>Feedback on a process or standard that readers cannot see, because it is a draft, is shown only to the people who may see the draft. For everyone else, its author included, it is as if it did not exist: it cannot be closed, reopened or deleted by them either.</dd></div>
          </dl>
        </Section>

        <Section id="bookmarks" title="Bookmarks, upvotes and sharing">
          <p>The bookmark and the upvote are on every card and at the end of the header of every process and standard; <b>Share</b> is next to them in the header, which also says how much it is used.</p>
          <dl className="guide-dl">
            <div><dt><Bookmark size={14} />Bookmark</dt><dd>Keeps a process or standard at hand. Your bookmarks are on <b>Home</b> under <b>Your bookmarks</b>, the newest first, and <b>Only my bookmarks</b> in the filters narrows any list to them. They are kept with your account, so they follow you to another computer or your phone. Nobody else sees them.</dd></div>
            <div><dt><ThumbsUp size={14} />Upvote</dt><dd>Says “this is useful”. Everyone sees how many upvotes a process or standard has; one per person, and pressing it again takes yours back, even when it has become a draft since. It tells owners what people rely on.</dd></div>
            <div><dt><Share2 size={14} />Share</dt><dd>On the page of a process or standard. The dialog shows its link, with a copy button next to it. Below: <b>Copy link and title</b> copies its name and the name of the portal, such as “Request a GCP project · Process Manager”, and the link on the next line, to paste in a chat or a document; <b>Email</b> opens your mail program with the subject and text filled in (“Have a look at the process … in Process Manager:”); and, where your browser offers it (often on a phone or tablet), <b>Share…</b> opens the device’s own way of sharing, to send it with an app. After copying the dialog says what was copied. Nothing is sent for you, and the link always leads to the whole process or standard. If your browser does not allow copying, the text is shown to copy by hand.</dd></div>
            <div><dt><Eye size={14} />Views</dt><dd>Opening a process or standard counts as a view, once per person per day however often you open it; a day runs from midnight to midnight UTC. Views by admins and editors count like anyone else’s. The portal counts views and different people; nobody, admins included, can see who viewed what.</dd></div>
            <div><dt>Skill downloads</dt><dd>How often the skill or review agent of a process or standard was downloaded from the portal: once per person per skill per day, like views, and nobody is shown who. Each run of an export that writes the skills to files counts one per skill. It stands for how much AI assistants use it; what they do with it afterwards is not counted, and neither are the questions assistants ask the portal over its MCP server.</dd></div>
          </dl>
          <p>Drafts stay hidden here too: what you may not see is not counted for you and not listed in your bookmarks, and you cannot newly upvote it. A draft that was never published has no views, upvote, bookmark or Share on its page; unpublished changes never change these numbers.</p>
        </Section>

        <Section id="requests" title="Asking for what is missing">
          <p>Missing a process or a standard? <b>Requests</b> in the top bar is where to ask for it, and where everybody sees what others asked for. Lists and searches that find nothing point there too.</p>
          <dl className="guide-dl">
            <div><dt><Lightbulb size={14} />Ask</dt><dd>Press <b>Ask for a process or standard</b>. Say which one is missing, give it a name (5 to 120 characters), and describe what is needed and why (10 to 1000). Add the platform and practice it would belong to if you know them: their owners can then take it up. While you type the name, processes, standards and requests with similar names are shown, so you can open what exists or vote for an earlier request instead of asking twice.</dd></div>
            <div><dt>Vote</dt><dd>Everyone can vote for a request, one vote per person, and take it back. The most wanted come first.</dd></div>
            <div><dt>States</dt><dd><b>Open</b> when it is asked; <b>Planned</b> when somebody takes it up, with a note such as when to expect it; <b>Done</b>, with a link to the published process or standard that answers it (a draft cannot answer a request; if the answer is deleted later, the request stays done and says that its answer was removed); or <b>Declined</b>, always with the reason. A request can be set back to open. The buttons at the top show the requests of one state, or all, and of processes, standards or both. Under <b>All</b> each request carries its state; under one state it is not repeated on every request.</dd></div>
            <div><dt>Who moves it along</dt><dd>Whoever could create what is asked for: admins; process editors for a process, standards editors for a standard; and the owners of the platform or practice the request names. The Owners of a team and the members of a platform or practice do not. On the requests they may move along they see the usual next step as a button, <b>Mark as planned</b> on an open request, <b>Mark as done</b> on a planned one and <b>Back to open</b> on one that is done or declined, and the other choices, such as <b>Mark as done</b> and <b>Decline request</b> on an open one, under <b>More</b> next to it.</dd></div>
            <div><dt>Withdraw and remove</dt><dd>Your own requests are marked “Yours”. While one is still open you can <b>Withdraw</b> it; it is removed for everyone, with its votes. An admin can <b>Remove</b> any request, in any state, after confirming; its votes are lost. Like the other choices, these are the button of a request when there is no other next step, and otherwise under More. One person can ask for up to ten requests an hour; withdrawn and removed ones count too.</dd></div>
          </dl>
          <ProcessPicture className="guide-fig" process={requestFlow} caption="The life of a request. Everyone sees each state, the note that comes with it, and in the end what answers the request or why not." />
        </Section>

        <Section id="mine" title="Your responsibilities">
          <p>If you are an owner of a team, a platform or a practice, or a member of a platform or practice, the top bar has <b>My responsibilities</b>. It covers what your teams maintain and what belongs to your platforms and practices; each entry says through which of them it is yours (“Google Cloud (member)” where you are a member), and if you have more than one, the buttons at the top narrow the page to one of them. The number next to the link is what is waiting for you: reviews that are overdue, feedback nobody has dealt with, and what waits for you to publish; pointing at the link says what it counts, such as “Waiting now: 1 feedback and 3 to publish”. At the top of the page, the number of reviews to do is in the colour of the worst of them, red when one is overdue and amber when they are only due, with a line that splits it, such as “6 overdue · 5 due” or “all overdue”.</p>
          <dl className="guide-dl">
            <div><dt><CalendarCheck size={14} />Reviews to do</dt><dd>What is overdue or due within a month, the most overdue first, each with when it was last reviewed and by whom, or “not reviewed since it was first published”, or “not reviewed yet”. <b>Open</b> it and read it; if it is still right, press <b>Still correct</b>. That records today, the day on your own calendar, and your name, as a version of its own, and a message confirms it: ““Request a GCP project” is recorded as reviewed today.” You do not have to be an editor for this: the review belongs to the team that owns the thing. If something has to change, change it (if you may) or ask somebody who may, then confirm.</dd></div>
            <div><dt><Flag size={14} />Feedback waiting for you</dt><dd>Every open item on what is yours, the oldest first: what was said, about which step or requirement, by whom, and how many others hit the same. <b>Mark as fixed</b> closes it and tells the person who reported it: “Marked as fixed. Sam Consumer is told.”, with <b>Undo</b>, which opens it again (the same on the page of the process or standard). Reopening or deleting feedback is confirmed the same way (“The feedback is open again.”, “The feedback was deleted.”); each confirmation replaces the one before it, so they do not pile up.</dd></div>
            <div><dt>Waiting for you to publish</dt><dd>For whoever can publish: drafts and unpublished changes somebody else saved last, the oldest first, such as “Draft by Morgan Member, 2026-11-22. Readers do not see it until you publish it.” or “Changes by Morgan Member, saved 2026-11-22. Readers still see version 1.” <b>Review and publish</b> opens it on the editing screen: read it through, change what is needed, then publish it. A tile at the top counts them.</dd></div>
            <div><dt>Your unfinished work</dt><dd>Unpublished changes you saved last yourself, with which version readers still see, and drafts that were never published, each with <b>Continue editing</b>; and things in use that nobody is asked to review because they have no review rhythm (it is set under About on the editing screen).</dd></div>
            <div><dt>Where you are a member</dt><dd>Where you are only a member, the page asks nothing else of you: “Where you are a member, you create drafts and suggest changes; an owner of the platform or practice publishes them, confirms reviews and answers feedback.” It has no tiles for reviews, feedback or publishing; instead it counts what has unpublished changes, and a draft of yours says “A draft waiting for an owner to publish it. Readers do not see it yet.” With nothing waiting it says “No draft is waiting for an owner.”</dd></div>
            <div><dt>Everything that is yours</dt><dd>Every process and standard of your teams, platforms and practices with its status (marked “Unpublished changes” when there are some), its next review, its open feedback, and its version with who changed it last, by name where the portal knows it, else by email (“Imported” for a version loaded from files, “Updated by the portal” for one the portal made itself).</dd></div>
          </dl>
          <p><b>Mark as reviewed</b> on the page of a process or standard does the same. If somebody published a change after you opened it, the review is not recorded: you are shown the current version first, so nobody confirms what they have not read.</p>
        </Section>

        <Section id="editing" title="The editing screen">
          <p>Whoever may change a process or standard, or write drafts of it as a member of its platform or practice, finds <b>Edit</b> on its page. It opens the <b>editing screen</b>: a screen of its own, with a dark bar across the top, so you always know whether you are reading or changing. <b>New process</b>, <b>New standard</b> and <b>Create from text with AI</b> on the lists create a draft and open it here. <b>Back to reading</b>, at the top left (on screens narrower than 1440 pixels just <b>Back</b>), returns to the page readers see. Below the bar the screen reads from left to right as you work: choose in the outline, change it in the fields right next to it, and see the result on the right, as readers will. The keyboard and screen readers meet them in the same order; <b>Skip to the page</b> goes straight to what readers will see.</p>
          <div className="guide-cards three">
            <div><List size={20} /><h3>Outline, on the left</h3><p>The parts of the process or standard, on the quieter grey of the page, so it reads as the way around; the item you chose is white, like the fields beside it. A process has <b>About</b>, <b>Before you start</b>, <b>Who takes part</b>, <b>Steps</b> (every step with its kind, number and the colour of its participant), <b>Links and resources</b> and <b>Standards it helps to meet</b>; a standard has <b>About</b>, <b>Scope and exceptions</b>, <b>Requirements</b> (every requirement with its level) and <b>Background</b>. A part with nothing in it says “none”. Each item shows how much the checker found in it and how much open feedback it has. At the end of the steps is <b>Add a step</b> (for a standard <b>Add a requirement</b>): see <b>Editing a process</b>.</p></div>
            <div><MousePointerClick size={20} /><h3>Its fields, next to the outline</h3><p>Every field of what is selected: a step, a requirement, or a part of the outline such as About. Type straight into them; there is nothing to switch on first. What is to fix there comes first; open feedback about a step or requirement is one line, such as “2 open feedback · “The form has moved””, which opens the whole list, because feedback is often why you are here. Beside “Step 3 of 10” (for a standard “Requirement 2 of 5”) are two arrows, <b>Previous step</b> and <b>Next step</b>, named after the step they lead to; Alt + Page Up and Alt + Page Down do the same while you type. The cursor stays in the same field: from the name of step 3 to the name of step 4, from an action to the first action of the next step, so you can write a process step by step without going back to the outline. At the first and the last step the arrow is there but unavailable. While a step or requirement is selected, the edge of the fields towards what readers will see takes the colour that marks it there, so you can tell at a glance that they belong together.</p></div>
            <div><Eye size={20} /><h3>What readers will see, on the right</h3><p>The name and summary, then the map of the process, or the requirements of the standard, as readers will see them once published, and changeable right there. For a process, what readers see before step 1 is folded into one line above the map (see <b>Editing a process</b>), so the map gets the height. While <b>About</b> is chosen, a second line under the name says what the head of the reader’s page will say about its fields, in the same words: the category and the team (“Cloud · Owned by Cloud Platform team”, or “Issued by” for a standard), for a process how binding it is and its lead time, then where it applies. Choose another team and the line follows at once; with no team chosen it says “No owning team yet”. Selecting something here selects it in the outline and shows its fields, to the left of it, and the other way round; pressing the name opens <b>About</b>.</p></div>
          </div>
          <p><b>The editing bar</b> at the top holds, from left to right:</p>
          <dl className="guide-dl">
            <div><dt>Its state</dt><dd>A coloured label, a second line about saving and one sentence. The label: <b>Draft</b> “Readers do not see this yet” (never published); <b>Published</b> “Version 7” (nothing changed); <b>Unpublished changes</b> “Readers still see version 7”; <b>Retired</b> “Readers see version 4, marked as retired”; <b>Deleted</b> “Readers no longer see it. Saving brings it back as a draft” (see <b>Somebody else deleted it</b>). The second line: <b>Not saved yet</b>, in amber, while you have changes you have not saved; <b>Draft saved 14:02</b> for changes kept in the draft (unpublished changes, or newer changes to a draft that still has something to fix); <b>Saved 14:02</b> or <b>Saved</b> otherwise; when somebody else saved last, their name follows, such as “Draft saved 10:29 by Alex Editor”. <b>Drafts and publishing</b> explains the states.</dd></div>
            <div><dt>Undo and redo</dt><dd>Point at Undo to see what it will undo. See <b>Versions, undo and working together</b>.</dd></div>
            <div><dt>The checker</dt><dd>“Nothing to fix”, “3 suggestions”, or “2 to fix”, in red, or in amber while only example text is left; checked on every change. Press it for the list, which opens over the fields, right above the fields it leads to, and never over the map: <b>To fix</b> and <b>Suggestions</b> (worth a look, never in the way). The heading of To fix says what it holds up: “stops publishing” (or “stops bringing it back”, for something somebody else deleted, see <b>Somebody else deleted it</b>); nothing on it stops Save draft. Choosing an entry closes the list, goes to the step, requirement or part it is about and puts the cursor in the field itself; Escape or a press outside closes it too. The entries say what to do, in the names of the fields as the screen shows them, such as “Write what happens in this step.”, “Link 1: start the address with https://”, “Write action 2, or remove it.”, “Name the answer, e.g. Approved.”, “Shorten the name: it holds at most 80 characters.”, “Choose the owning team: it reviews the process and answers feedback.” or “Cyber Security takes part but has no steps.”; something that has no name yet is named by its place, such as “Step 3 (no name yet)”. The fields of a step or requirement say the same at the top, such as “2 to fix before publishing” or “1 to fix before publishing: example text”, and the outline marks the item with the number. Suggestions about a step or requirement you just added wait until you have left it once, so they do not interrupt you while you write it.</dd></div>
            <div><dt>Problems on the field</dt><dd>A field that has a problem says so itself, the moment it has one: it is outlined in red, with what to do in a line under it, such as “Write what happens in this step.”; a field that still holds example text is outlined in amber instead, with “… is still the example text: write your own.”. Screen readers read the same line with the field.</dd></div>
            <div><dt>More</dt><dd><b>Versions</b> (see and restore earlier ones), <b>Change with AI</b>, <b>JSON</b> (the text of the whole document), <b>Discard draft…</b> (while changes are kept in the draft), <b>Retire…</b> or <b>Bring back into use…</b> and <b>Unpublish…</b> (for something published), and <b>Delete…</b>; the last four only for whoever may publish it. An item that cannot be used right now says why, such as “Publish or discard the unpublished changes first.”</dd></div>
            <div><dt>The actions</dt><dd><b>Discard changes</b> goes back to what you last saved (Undo brings it back); when everything is saved and changes are kept in the draft, it becomes <b>Discard draft…</b>. <b>Save draft</b> keeps your changes without showing them to readers (Ctrl+S, ⌘S on a Mac), always, also while something is still to fix; a dot on it means there are changes not saved yet. <b>Publish…</b>, the last and most visible button, makes them what readers see.</dd></div>
            <div><dt>When something is in the way</dt><dd>Save draft and Publish… can always be pressed while there is something to save or publish. While something is to fix, Publish… looks unavailable, and pointing at it says what comes first: “First fix the 2 things listed under “2 to fix”.” or, when only example text is left, “First replace the 3 example texts with your own words (under “3 to fix”).” Pressing it opens the checker’s list by itself with that reason at its top and selects the first thing to fix. When something else is in the way, such as a platform that is not yours, the reason starts with “This cannot be published yet.” (for Save draft “This draft cannot be saved yet.”). Save draft is held up only by such a reason, or by text in the JSON view that still has something to fix: whatever the checker finds, the draft is saved.</dd></div>
            <div><dt>If you may not publish it</dt><dd>A member of its platform or practice, and an owner who may not publish this one (see <b>The first publication</b> under <b>Teams, platforms and practices</b>), works the same way up to Save draft. Publish… looks unavailable, and a line on the editing screen says who publishes, by name where the portal knows it: “Jordan Platform, an owner of Google Cloud, publishes this. Your draft is saved for them.”, “An owner of Google Cloud publishes this: Jordan Platform or ann@example.com.”, “Somebody who owns both Google Cloud and Engineering publishes this: Jordan Platform.”, or, when nobody owns it yet, “Google Cloud has no owner yet: a process editor publishes this.” While changes are not saved it ends “Save draft keeps your work for them.” instead. Pressing Publish… shows “An owner publishes this: see above.” in the checker. The owners find what you saved under <b>My responsibilities</b>, in “Waiting for you to publish”; a member cannot mark a draft as ready for them.</dd></div>
          </dl>
          <p><b>Example text.</b> A new process or standard, and every new step or requirement, starts with example text such as “First step” or “Describe in one or two sentences…”, to show what goes where. A field that still holds it selects it when you enter it, so what you type replaces it. Example text left in has to be replaced before publishing, such as “Summary is still the example text: write your own.”, so a new process opens with “3 to fix” in amber. This is shown calmer than a real problem; it does not stop you from saving the draft. A field that is merely empty shows a pale hint of what could go in it, starting with “e.g.”, such as “e.g. 3-5 working days”; the hint is never saved.</p>
          <p><b>Starting a new process.</b> A process that was never published and has no more than two steps shows <b>Start here</b> under its name: <b>Write the summary</b>, <b>Add the steps</b> and <b>Open the first step</b>, each ticked off once done, then Publish… (for whoever may not publish it: “Then Save draft: an owner publishes it.”).</p>
          <p><b>The map on the editing screen</b> follows the same rule as the reader’s map: it opens at its start, as large as lets the flow fit the width or the height of the column, whichever is larger, but never above 100% and never below 60%, and <b>Fit</b> shows the whole flow, at whatever size that takes. The map fills the column down to the bottom of the screen (on a phone too), so you see as many lanes and steps as fit. Fit is an overview here as well: selecting a step, or any change you make, returns the map to the size it opened at, with the step in the middle. Instead of the legend it has a <b>Legend</b> button, and a line that reminds you what you can do on it: “+ on an arrow inserts a step · drag a block to another lane · loop back” (on a touch screen without the dragging; on a phone the line is left out). Selecting a step, in the outline, on the map or from the checker, moves the map (not the page) so that the step stands in its middle, with room for where it leads, also after adding or moving it, and again when the column of the map changes width, as when the window does.</p>
          <dl className="guide-dl">
            <div><dt>A narrow outline</dt><dd>On a screen 1280 pixels wide or more the outline is open, with the names. If you want more room for the map, the button at the top of the outline, <b>Narrow the outline</b>, makes it a narrow strip with only the icons of the parts and the numbers of the steps; point at one to read its name, and <b>Show the outline with names</b> widens it again. The portal remembers your choice in this browser. On a screen from 1100 to 1279 pixels wide the outline is always the narrow strip, so the fields and the map keep their room: every part has its icon there, About, Before you start, Who takes part, Steps, Links and resources and Standards it helps to meet (for a standard About, Scope and exceptions, Requirements and Background), with the numbers of the steps, the problems and a small flag for open feedback. <b>Show the outline with names</b> opens the whole outline over the fields for a moment; choosing something in it closes it again.</dd></div>
            <div><dt>Keyboard</dt><dd>The outline is one stop for the Tab key: the up and down arrows, Home and End move from item to item, Enter opens its fields with the cursor in the first field (or on the first button, for a part that has no field), and Alt with the up or down arrow moves a step or requirement; Enter on a step puts the cursor in <b>What happens</b>. The blocks of the map are one stop for the Tab key too: the arrow keys, Home and End move from step to step in the order of their numbers, and Enter selects the step and puts the cursor in What happens. The kinds of step under <b>Kind of step</b> are one stop for the Tab key too: the arrow keys move through them, Home and End go to the first and the last, and Enter chooses. <b>Add step after</b> puts the cursor in the name of the new step; adding somebody under <b>Someone else</b> with Enter moves the focus to their new button. Escape in the fields goes back to the item in the outline. Alt + Page Up and Alt + Page Down go to the step or requirement before or after, with the cursor in the same field. Ctrl+S saves the draft, Ctrl+Z undoes and Ctrl+Shift+Z redoes (⌘ on a Mac).</dd></div>
            <div><dt>Messages</dt><dd>What a change did, such as “Step “Point DNS to Akamai” deleted.” with <b>Undo</b>, appears at the bottom of the fields, as wide as they are, never on the map. If it would cover the field you are typing in, the fields move up so that the field stays in sight. A newer message replaces the one before.</dd></div>
            <div><dt>Smaller screens</dt><dd>On a screen narrower than 1100 pixels the fields stay on the left and what readers will see on the right, and the outline slides in from the left, over the fields, when you press <b>Outline</b>; choosing something in it closes it, and the fields of what you chose are right there. On a phone what readers will see takes the whole width, and the fields slide over it too: <b>Outline</b> and the name of what is selected open them. On a phone the bar has two rows, More also holds Undo, Redo and Discard, the map takes the rest of the height, messages appear just under the editing bar so they never cover the map, and the fields have one button at the top, <b>Back to the map</b> (for a standard <b>Back to the requirements</b>).</dd></div>
            <div><dt>If the screen cannot show something</dt><dd>Should a part of the editing screen fail to show, it says “The editing screen could not show this”: a fault in the portal, not in your work, and your changes are still there. It offers <b>Undo the last change</b> (which usually brings the screen back), <b>Try again</b>, <b>Save draft</b> while something is not saved yet, and <b>Back to reading this process</b> (or standard); when everything is saved it says “Everything is saved: nothing on this screen is lost.” Under <b>What went wrong, for the people who run the portal</b> is what to pass on to them.</dd></div>
          </dl>
          <p>The editing screen shows nothing readers use: no views, upvotes, bookmark or Share. Opening a step or a requirement changes the address, so a link can lead a colleague straight to it on the editing screen.</p>
        </Section>

        <Section id="publish" title="Drafts and publishing">
          <p>Readers only ever see what was <b>published</b>. Until you press Publish, nothing you change reaches them: not on the page, not in search, not in the skills and not for AI agents. There are two kinds of “not published yet”:</p>
          <dl className="guide-dl">
            <div><dt>Draft</dt><dd>Something that was never published, or was unpublished again. Only the process editors (for a standard the standards editors), the owners and members of its platform or practice, and the Owners of its team can open it; for everyone else it does not exist, not in the lists and not by its link. <b>Save draft</b> always works. With nothing to fix, it stores the draft as the process or standard itself, as a version of its own: that is what its page and the lists show to everyone who may see its drafts, the Owners of its owning team included. While something is still to fix, your changes are kept beside it as newer changes, which only the people who may write drafts of it see on the editing screen (its page tells them “There are newer changes on the editing screen…”); the first Save draft with nothing left to fix stores them as the process or standard itself. <b>Publish…</b> makes it visible to everybody who signs in: its skill is generated, and search and AI agents find it. A draft cannot be retired: publish it first, or delete it.</dd></div>
            <div><dt>Unpublished changes</dt><dd>Changes to something published. They are kept beside the published version, as one shared draft that everybody who may write drafts of it works on, members of its platform or practice included, until somebody who may publish it publishes them, or somebody discards them. Readers keep seeing the published version, and nothing tells them that changes are under way. <b>Save draft</b> works even while something is still to fix, so an unfinished change can wait. The people who may write drafts of it see “Unpublished changes” on its card, on its page (with who saved them last and <b>Continue editing</b>) and under <b>My responsibilities</b>.</dd></div>
          </dl>
          <ProcessPicture className="guide-fig" process={changeFlow} caption="The life of a change. Nothing reaches readers before Publish. If somebody else published in the meantime, you compare and choose; a draft can also be thrown away." />
          <p><b>A member writes, an owner publishes.</b> The members of a platform or practice write drafts and changes, and an owner of that platform or practice (or an editor) publishes them. The member presses Save draft; the owner finds the draft under <b>My responsibilities</b> in “Waiting for you to publish”, presses <b>Review and publish</b>, reads it through on the editing screen, changes what is needed, and publishes it. The Publish dialog names whose work it is, the list of versions keeps it, and so does <b>Admin › Activity</b>.</p>
          <ProcessPicture className="guide-fig" process={memberFlow} caption="A draft by a member of a platform or practice. The member saves it; an owner reads it through and publishes it. A member cannot mark a draft as ready: the owner sees what waits." />
          <dl className="guide-dl">
            <div><dt>Publish…</dt><dd>Opens a last check before readers see it, titled <b>Publish your changes</b>, or, when somebody else saved the changes last, with their name, such as <b>Publish Morgan Member’s changes</b>, and “Last saved by Morgan Member at 2026-11-22 05:17.” (your own unsaved changes make them yours). Under <b>What readers will see differently</b> it shows what changed compared with the version readers see now (“Until you publish, readers see version 7.”), in words, with the old and the new text (old → new) for short fields such as the name, and with names rather than codes, such as who does a step: “You” → “Site Reliability team”; and a <b>Note for the list of versions</b> (its hint reads “e.g. Added the security review”, or “e.g. First version” the first time). The note is optional and worth the ten seconds: it is what others read in the list of versions. While something is to fix the dialog does not open; the checker’s list says what first. For something never published, the dialog is titled <b>Publish this process</b> (or standard) and says who could see it until now: “Until now only the process editors, the owners and members of its platform or practice, and the Owners of its team could see it.” Readers see it as soon as you publish; changes you had not saved yet are published with it.</dd></div>
            <div><dt>Discard draft…</dt><dd>Throws the changes kept in the draft away, for everybody who edits it, after you confirm. For something published (“Discard the unpublished changes?”), readers keep the version they had. For a draft that was never published (“Discard the newer changes?”), it goes back to how it was last stored as the process or standard itself, and the screen says “The newer changes were discarded. The draft is back to how it was last stored as the process itself.” It cannot be undone, and it is in <b>Admin › Activity</b>.</dd></div>
            <div><dt>When it cannot be stored as itself</dt><dd>Rarely, the portal refuses to store a draft as the process or standard itself even though the screen found nothing to fix, for example because of a rule only the portal checks. Your work is then still kept, as the draft’s newer changes, and a message that stays until you close it says “Saved as a draft, not yet as the process itself.” with the portal’s reason and “Fix this before publishing.” The checker lists the same reason under To fix (“At the last save it could not be stored as the process itself: …”), so Publish… waits for it; the entry goes away once a save stores it as itself.</dd></div>
            <div><dt>Reviews meanwhile</dt><dd>Somebody may confirm a review on the published version while changes are being made. That is kept when the changes are published, without a question, and it does not count as somebody publishing in between.</dd></div>
            <div><dt>While there are unpublished changes</dt><dd>The process or standard cannot be retired, unpublished or brought back into use: publish or discard the changes first. Deleting it deletes them too.</dd></div>
          </dl>
        </Section>

        <Section id="edit" title="Editing a process">
          <p>On the editing screen the column on the right shows the map, and above it the name, the summary and “Before you start” as readers will see them; pressing the name opens <b>About</b>. “Before you start” is one line there, so that the map has the room: how many things are needed (“3 needed”, or “nothing needed”), the links (“2 links” or “no links”) and the standards it helps to meet (“1 standard” or “no standards”), each a button that opens its fields, and <b>Show</b> (then <b>Hide</b>) to unfold it as readers see it. A link without a name yet, which readers do not see, is counted apart: “1 link (1 without a name)”. A new process starts with its name: the name gives it its address, which never changes afterwards. If you may change only what belongs to your platforms and practices, you also choose which of them it belongs to.</p>
          <div className="guide-cards three">
            <div><Plus size={20} /><h3>Adding steps</h3><p>Quickest: under <b>Add a step</b> at the end of the outline, type the name of a step, press Enter, type the next one (Escape closes it); on a blank process the first name replaces “First step”. On the map, the small + on an arrow (it appears when you point at the map) opens a form right there: what happens, who does it, what kind; the step lands exactly between the two blocks. The + on a block, and <b>Add step after</b> in the fields of a step, add one after it; on a decision they add a branch. A new decision starts with a “Yes” and a “No” path.</p></div>
            <div><GripVertical size={20} /><h3>Moving steps</h3><p>Drag a step by its handle in the outline, press Alt with the up or down arrow on it, or choose <b>Move…</b> in its fields (“Before 3. Approve the budget”, “To the end”). Drag a block on the map to another lane to change who does it; drag the map itself by an empty spot.</p></div>
            <div><ListChecks size={20} /><h3>The fields of a step</h3><p>In the order a step is written: <b>What happens</b>; <b>Who does it</b>; the <b>Kind of step</b>; <b>What to do</b>, exactly, one action per line; <b>What comes next</b>; and <b>More about this step</b>. At the top: add a step after it, move it, or delete it.</p></div>
          </div>
          <dl className="guide-dl">
            <div><dt>Who does it</dt><dd>One button per participant. <b>Someone else</b> asks who else takes part (a team from the lists, or any role or system); <b>Add and give them this step</b> adds them as a new participant, with a lane of their own, and gives them this step.</dd></div>
            <div><dt>Kind of step</dt><dd>A button with the kind it has now and a sentence on when to use it; press it to choose among the thirteen kinds, listed in two columns (see <b>The building blocks</b>). A step that becomes a decision gets a “Yes” that keeps where the flow went and a “No” that goes back to the step before. The screen says so at once, such as ““No” goes back to “Ask your manager to approve”. Change it under “What comes next”.”, and brings that answer into view under What comes next, briefly marked. The same happens when you add a new decision on the map.</dd></div>
            <div><dt>What to do</dt><dd>The exact actions, which readers tick off. Enter starts the next one; Backspace in an empty one removes it. When a step of the reader (the first participant) is work done by hand, such as Fill in a form, Approve, Meeting or Task, and has no actions and no sub-process, the checker suggests “Say exactly what the reader does in this step.” It does not ask this of a decision, a wait, an automated step or a sub-process, nor of the steps of the other participants.</dd></div>
            <div><dt>What comes next</dt><dd>In sentences: “Then” and the step that follows, “Several ways on”, “One branch per answer” for a decision, each answer with a name such as Approved or Rejected, or “The process ends here”. <b>Continue to a step</b> or <b>Add another way on</b>, <b>Add a branch</b> on a decision, and <b>Go back to an earlier step</b> for a loop, for example to correct something. Each answer of a decision has its name on top and the step it goes to below it, both the full width of the fields. <b>Add a branch</b> adds an answer called “Other” that goes to the next free step, selects its name so you can type over it, and says so: “Answer “Other” added: it goes to step 6 “Roll out to 10%”. Name it, and choose where it goes.”</dd></div>
            <div><dt>More about this step</dt><dd><b>Context</b>, <b>Tool</b>, <b>Typical time</b>, <b>Result</b>, <b>Link</b>, <b>Skills and links</b> and <b>Sub-process</b> are shown when the step has them; the others are offered as small “+” buttons under <b>Add to this step</b>.</dd></div>
            <div><dt>Moving changes the flow</dt><dd>A step is moved in the flow, not only in the numbering: the steps before it are joined to what came after it, as if it had been taken out, and it is put on the way into the step it now stands before, and leads there. The numbers follow. A decision moves with its answers: the answer that carried the flow on is the one that is reconnected, the others keep where they lead. A short message says where the step is now, such as “Step “Change approved?” is now step 14, the last.”, “… is now step 1, the first.” or “… is now step 8, before “Deploy to production”.”, with <b>Undo</b> (pointing at Undo on the bar says “Undo: move of step “Change approved?””).</dd></div>
            <div><dt>Deleting a step</dt><dd>The bin at the top of its fields deletes it at once, without a question. Just after a step is selected the bin is unavailable for a moment (it looks faded, and pointing at it says “Delete step (available in a moment)”), so a double press cannot delete the next step too. A short message says what happened, with long names cut off, such as “Step “Start the production deployme…” deleted.”, and offers <b>Undo</b>; Undo on the bar works too. The step that took its place is selected, in the outline, so you can go on with the keyboard. The steps before it are joined to what came after it. An answer of a decision keeps its name: an answer that led to the deleted step now leads where that step led (when it had several ways on, the one that carried the flow on). An answer that led to a deleted step that ended the flow is removed. If two answers then lead to the same step, the checker asks you to let each lead somewhere else.</dd></div>
            <div><dt>What the message says</dt><dd>After a move or a delete, the message also says, one line each, everything else that changed in the flow, and where things go now by the number and name of the step: ““No” of “Is it a tier 0 service?” now goes to step 9 “Start the production deployment”.”, ““Yes” of “Release healthy?” is removed: it led to the deleted step, which ended the flow.”, ““Other” of “Change approved?” is new: it goes to step 6 “Roll out to 10%”.”, “Nothing leads to step 4 “Fix the request” any more.” or ““Close the change record” now leads to step 14 “Change approved?”.” It shows at most three such lines; beyond that the third says “And 2 more: see “What comes next” of the steps on the map.” Only one message is shown at a time: a new one replaces the one before, and they end when you leave the editing screen.</dd></div>
            <div><dt>About</dt><dd>Name and summary, owning team and typical lead time. Below, folded, each with a line that says what is set: <b>What it belongs to</b> (category, platform, practice) and how binding it is; <b>Where it applies</b> (tiers, environments, languages) and tags; and <b>Review</b>, the review rhythm. A folded group opens by itself when the checker finds something to fix in it.</dd></div>
            <div><dt>The other parts</dt><dd><b>Before you start</b>: the prerequisites, each with a name and a few words about it, in boxes that grow with the text, and possibly provided by another process; Enter in a name adds the next, Backspace in an empty one removes it. <b>Who takes part</b>: the lanes, the first always the reader; each participant has a name and a few words about them, in a box that grows with the text, and under them how many steps they have, the arrows to move them a lane higher or lower on the map, and <b>Remove</b>; a lane that still has steps cannot be removed. <b>Links and resources</b>, each link a block with its number, its kind and a cross to remove it (“Remove this link”) on top, then <b>Name</b>, <b>Address</b> and <b>What it does for the reader</b>, whose labels stay when the field is filled in; and <b>Standards it helps to meet</b>. Readers see both under “Before you start”.</dd></div>
          </dl>
        </Section>

        <Section id="editstandard" title="Editing a standard">
          <p>Standards editors can change every standard; platform and practice owners the standards that belong to theirs. On the editing screen the column on the right shows the name and summary, then one line for <b>Scope and exceptions</b> (such as “scope written”, “exceptions: ask the issuing team”, “2 background links”, each a button that opens its fields, and <b>Show</b>, then <b>Hide</b>, to unfold it as readers see it), then the requirements as readers see them; select one, there or in the outline, to change it in the fields next to the outline. A standard that was never published and still has its example requirement shows <b>Start here</b> under its name: <b>Write the summary</b>, <b>Add requirements</b> and <b>Open the first requirement</b>, each ticked off once done. Under <b>Add a requirement</b> at the end of the outline, type the short name of a rule, press Enter and type the next (on a new standard the first name replaces the example requirement); <b>Add requirement after</b> in the fields of a requirement adds one after it. The numbering continues. Move a requirement by its handle in the outline, with Alt and the up or down arrow, or with <b>Move…</b> in its fields. The bin deletes it at once; the message “Requirement SEC-LOG-06 “…” deleted.” offers <b>Undo</b>.</p>
          <dl className="guide-dl">
            <div><dt>The rule</dt><dd><b>Level</b> (Must, Should or May) first, then the <b>Short name</b>, <b>The rule</b> in one testable sentence or two, <b>Why</b>, and the id. Keep the id stable: people and tools cite it. A changed id is taken over when you leave the field. An id that cannot be used, because another requirement has it or it is not written like SEC-LOG-07, is refused with a message saying why, such as “Write the id in capitals and digits in groups joined by dashes, e.g. SEC-LOG-07. … the requirement keeps REQ-01.”, and the field shows the id the requirement keeps again; so does an id you emptied (“Give the requirement an id, e.g. SEC-LOG-01. It keeps REQ-01.”).</dd></div>
            <div><dt>How to comply</dt><dd>The steps to comply (Enter adds the next, Backspace in an empty one removes it) and a process that helps.</dd></div>
            <div><dt>Folded groups</dt><dd><b>Good and bad examples</b>, <b>How it is checked</b> (automatically, in code review, or by a person, and by what), <b>For reviewers</b> (the signs of a violation in a pull request, the files where it matters, one pattern per row, and how a finding is reported: blocker, warning or info; leave it empty for rules that cannot be seen in a change; this is what the review agent is built from) and <b>Applies only to</b> (a requirement can be narrower than its standard, for example “production only”). Each shows in a line what it holds, and opens by itself when the checker finds something to fix in it.</dd></div>
            <div><dt>About, scope and background</dt><dd>Under <b>About</b>: name and summary, the team that issues it, then, folded, what it belongs to and the review rhythm. How binding a standard is follows from the levels of its requirements, so it has no setting of its own. <b>Scope and exceptions</b>: what it covers, how to ask for an exception, and where it applies (tiers, environments, languages) with its tags. <b>Background</b>: policies and other reading behind it. A new standard starts with its name and the team that issues it.</dd></div>
          </dl>
        </Section>

        <Section id="versions" title="Versions, undo and working together">
          <p>Every publish is a <b>version</b>: numbered, with who published it, when, and the note they left. So is every save that stores a draft that was never published as the process or standard itself, every review and every retirement. Nothing is ever overwritten without a trace, and nothing you typed is dropped without asking.</p>
          <dl className="guide-dl">
            <div><dt><History size={14} />Versions</dt><dd>The header of a process or standard shows the version. Press it for the list: every published version with its note and who saved it, by name where the portal knows it; “Imported” for a version loaded from files, “Updated by the portal” for one the portal made itself, for example when it converted content to a new version of the portal. Each version shows who stored it and when (“… · stored 2026-11-20 10:29”); when somebody published changes another person saved last, it names both: “published by Jordan Platform · changes last saved by Morgan Member · stored …”. <b>What changed</b>, on every version but the first, compares it with the one before it, in words: which steps or requirements were added, removed or changed. Everyone who can read it can see this. On the editing screen, <b>More › Versions</b> also offers <b>Restore</b>: it puts that version into your draft on this screen. Nothing is kept until you save the draft, and readers see nothing until you publish; Undo takes it back. For something published the list holds the published versions, and says so: “Every published version is listed here; your saved draft is not.”</dd></div>
            <div><dt>Undo</dt><dd>Every change on the editing screen can be undone and redone with the arrows on the editing bar or with Ctrl+Z and Ctrl+Shift+Z: a deleted step, a block dragged to the wrong lane, a result pasted from the AI dialog, a restored version, even <b>Discard changes</b>. Each action is a step of its own; typing in one field counts as one step until you pause. Pointing at Undo tells you what it will undo; afterwards a message says what is true now, and what came back is selected: “Step “Approve” is back.” after undoing a delete and “Step “Approve” is deleted again.” after redoing it; “Step “Approve”: who does it, what to do as before.” and, after Redo, “… changed again.”; “Participant “Change manager”: name as before.”; “Prerequisite “Access to the billing account” is back.”; “Link “Supplier form” is gone again.”; “Application tiers are as they were.”; after undoing or redoing a move, “Step “Approve” is back in its place.” and “Step “Approve” is moved again.”; “Platform is “Google Cloud” again.”; or simply “Undone.” and “Done again.”. Something without a name yet is named by its place, such as “Step 3 (no name yet) is back.”</dd></div>
            <div><dt>Leaving</dt><dd>With changes you have not saved, every way out asks first: Back to reading, another page, the Back button, signing out, closing the tab. Leaving the editing screen asks “Save your changes before you leave?” with three answers: <b>Save draft and leave</b> (the main one), <b>Stay</b> and <b>Leave without saving</b>. Save draft and leave is offered only when the changes can be saved; when the save is refused you stay, and the checker says why. Elsewhere, such as the lists in the Admin panel, the question is “Leave without saving?” with Leave without saving and Stay. Moving between the steps and parts of what you are editing keeps the changes. Text in the JSON view that still has something to fix is not part of the draft, so leaving it asks too.</dd></div>
            <div><dt>Somebody else saved the draft first</dt><dd>Two people can work on the same draft. A newer save of a colleague is never overwritten without a question, also not one of your own from another tab. When they saved while you were editing, a line on the editing screen says so as soon as the portal knows, such as “Dana Admin saved newer changes to the draft at 2026-11-20 10:29 while you were editing. Your changes are still here.” (for something published: “… saved the unpublished changes …”), with <b>Compare and decide</b>. Save draft then does not carry out your save either: “Somebody else saved the draft first” shows what they changed and lets you choose <b>Use their draft</b> or <b>Save mine over theirs</b>. Use their draft continues from what they saved; Undo then puts your whole version back as it was, also where theirs is newer: nothing is merged. For a draft that was never published and saved by somebody else as a version of its own, it works the same way with their version (“Use their version”).</dd></div>
            <div><dt>You, in two windows</dt><dd>If you edit the same thing in two windows or tabs, the portal knows it was you: the question then reads “You saved the draft in another window first” (or “You published in another window first”), with the same choices.</dd></div>
            <div><dt>The unpublished changes are gone</dt><dd>If somebody published or discarded the changes while you were editing, yours are still on your screen. The dialog says what happened and, where the portal knows it, who: “Dana Admin published it as version 2 at 2026-11-20 07:30, while you were editing.”, or that the shared draft was discarded. For a draft that was never published it is called “The newer changes are gone”, and says, for example, that somebody “saved the draft with nothing left to fix as version 3”. <b>Save mine as a new draft</b> keeps them as new unpublished changes. If something was published meanwhile, you are shown what changed and asked before yours is published over it, as below.</dd></div>
            <div><dt>Somebody else published first</dt><dd>If a newer version was published after your changes were started, a line on the editing screen says so: “Version 8 was published after these changes were started from version 7. Publishing will show what changed in it and ask whether to publish yours over it.” In the Publish… dialog, a line of <b>What readers will see differently</b> that would take back their change is marked “This would undo a change Dana Admin published since you started”. Publish then asks before anything happens: you see what they changed and choose <b>Publish mine over theirs</b> (theirs stays in the list of versions) or <b>Continue from theirs</b>, which puts their version on your screen, not saved yet: Undo brings your own changes back, and Save draft continues from theirs. Nothing is merged: Continue from theirs starts from their version, and Publish mine over theirs replaces it; a change of theirs you want to keep has to be made again in yours. A review confirmed meanwhile is not such a conflict.</dd></div>
            <div><dt>Somebody else retired, unpublished or published it</dt><dd>When somebody else changed what readers see while you were editing, the next time your draft is saved a line on the editing screen says so, for example “Dana Admin retired this process at 2026-11-20 10:40, while you were editing. Readers see it marked as retired. Your changes are saved as unpublished changes.” (and the like for unpublishing it, publishing it or bringing it back into use). Publishing over such a change asks first, titled for example “Dana Admin retired it first”.</dd></div>
            <div><dt>Somebody else deleted it</dt><dd>If what you are editing is deleted by somebody else, it stays on your screen, marked <b>Deleted</b>. Saving then tells you, with your changes still there and, when you could change it, with who did it, such as “Dana Admin deleted this process while you were working on it.”, and offers <b>Save mine and bring it back</b>: it comes back as a draft, so readers see it (again) only when you publish. It is brought back only with nothing to fix (“This process cannot be brought back yet: …”): until then the checker’s list, headed “stops bringing it back”, says what, and goes there. Deleting works on the version you are looking at: if somebody changed it since, it is not deleted.</dd></div>
            <div><dt>Up to date</dt><dd>When you come back to the tab, the portal fetches what others changed in the meantime. If you have unsaved changes they are kept, and a notice tells you that there is something newer. The lists are protected the same way; there you are told who saved, without the comparison.</dd></div>
          </dl>
          <ProcessPicture className="guide-fig" process={versionFlow} caption="A save is only carried out on top of the latest save of the draft. Otherwise you compare and decide; either way nothing is lost without asking." />
        </Section>

        <Section id="ai" title="Creating one with AI">
          <p>You do not need a particular AI product. The app builds one self-contained prompt that works in any chat assistant you are allowed to use, such as Gemini or Copilot in the browser, and checks whatever comes back. Nothing is sent anywhere by the app itself. This works for processes and for standards.</p>
          <ProcessPicture className="guide-fig" process={aiFlow} caption="From free text to a checked process. If the answer has problems, the app writes the fix request for you to send to the same chat. Afterwards you review, adjust and publish on the editing screen." />
          <p>The prompt contains the rules a process or standard follows, how it must be written down, your current lists, what already exists (so it can be linked) and one worked example. <b>More › Change with AI</b> on the editing screen works the same way and adds the current content to the prompt. Before you use the answer, the dialog lists <b>What changes in your draft</b>, with how many, in the same words as the Publish… dialog. <b>Apply to draft</b> puts the result on the editing screen, not saved yet, and says “The changes from the AI chat are in your draft, not saved yet.”, with <b>Undo</b>. When the answer has problems, the dialog lists each with its place and what to do, such as “Step 3 “Approve” Write what happens in this step.”, and the fix request you send back to the chat also quotes the value that is wrong.</p>
          <p>Whatever is created this way starts as a draft that readers do not see, whatever the answer of the assistant says, and never replaces something that exists: if the name is taken, the new one is created next to it.</p>
          <p><b>More › JSON</b> on the editing screen shows the text of the whole process or standard in a code editor, for those who prefer it. Changes that pass the checks go into the draft as you type; <b>Back to the editor</b> returns. What is to fix is listed beside the text in the same words as on the editing screen, each starting with where it is, such as “Step 3 “Approve the request””, and ending with its place in the text in small letters; pressing one shows that line, and pointing at the marked line in the text says the same. If the text still has something to fix, it asks first, “Leave the JSON without its changes?”, since those changes are not part of the draft. A process or standard stored with problems so bad that it cannot be shown opens here, with <b>Repair it</b> on its page for the people who may change it.</p>
        </Section>

        <Section id="lifecycle" title="Life-cycle and reviews">
          <p>A description that nobody checks goes stale. Every process and every standard therefore has a state and a review rhythm (under About on the editing screen).</p>
          <dl className="guide-dl">
            <div><dt>Draft</dt><dd>Being written, never published. Only the editors of its kind, the owners and members of its platform or practice and the Owners of its owning team get to see it: for everyone else it does not exist, not in the lists and not by its link. No skill is generated. New processes and standards start here; <b>Publish…</b> makes it active; however it is published, the activity log records it as its publication.</dd></div>
            <div><dt>Active</dt><dd>Published, in use and visible to everyone. The owner is asked to review it every 3, 6, 12 or 24 months. Changes to it are unpublished changes until they are published.</dd></div>
            <div><dt>The first review</dt><dd>Is counted from the day it was first published (your day, where you are), not from when its first draft was written. Until then the page says “First review due …” quietly; from a month before that date it is marked as due (“First review due …” in amber), after it as overdue (“Review overdue since …” in red), as every later review is.</dd></div>
            <div><dt>Retired</dt><dd>No longer the way to do it. <b>More › Retire…</b> asks what readers should use instead, if anything. It stays for reference, greyed out, and points to what replaces it. Its skills are withdrawn. <b>More › Bring back into use…</b> makes it active again. Only what was published can be retired: a draft is published first, or deleted.</dd></div>
            <div><dt>Unpublish and delete</dt><dd><b>More › Unpublish…</b> takes an active or retired one back from readers: it becomes a draft again, its skills are withdrawn and search and agents no longer find it, and it can be published again later. <b>More › Delete…</b> removes it for everyone, with its unpublished changes and its feedback; readers’ links stop working.</dd></div>
          </dl>
          <ProcessPicture className="guide-fig" process={reviewFlow} caption="The review cycle of an active process or standard. “Mark as reviewed” records the date and who confirmed it." />
          <p><CalendarCheck size={13} /> Owners find what is due under <b>My responsibilities</b>. The lists and the search results offer <b>Only what needs a review</b> to whoever looks after something that is due, and their cards and pages show “Review due …” in amber or “Review overdue since …” in red; the number next to My responsibilities counts what is overdue; <b>Admin › Health</b> lists everything that is due, for all teams. All of them, and AI agents asking over the MCP server, count the first review the same way. Due and overdue are counted by your own day; agents and the command line have no calendar of their own and count by the day in UTC, so for a few hours around midnight a review can be due for them a day earlier or later than for you.</p>
          <p><b>Mark as reviewed</b>, on the page readers see, records the review at once, as a version of its own with the note “Reviewed: confirmed as still correct” and the date of your day: in Auckland in the morning, or in Los Angeles in the evening, that is the date on your calendar, even when it is already another day elsewhere. If your computer’s clock is far off, the portal records its own date instead (the day in UTC). The date of the last review never goes back: when somebody ahead of you in time already confirmed it on their later date, that date stays. It is shown to the Owners of its owning team as well as the people who may change it, not to the members of its platform or practice; see <b>Your responsibilities</b>. Unpublished changes do not stand in its way.</p>
        </Section>

        <Section id="skills" title="Skills and review agents">
          <p>The portal turns what it knows into instructions for AI coding assistants. They are generated by fixed templates, not by AI, so the same source always gives the same text.</p>
          <dl className="guide-dl">
            <div><dt>Process skill</dt><dd>“Follow this process for a person”: the prerequisites, your steps with the exact actions, what to wait for from others. It tells the assistant never to approve anything and to ask before it submits.</dd></div>
            <div><dt>Standard skill</dt><dd>How to write code and configuration that complies: every requirement with its reason, how to comply and examples.</dd></div>
            <div><dt>Review agent</dt><dd>A reviewer for pull requests: what to look for per requirement, in which files, how severe a finding is, and how to report it with the requirement id.</dd></div>
            <div><dt>Whom to ask</dt><dd>Each names the owning team, the platform and the practice with how to reach them, in a fixed order: group email, Slack, Google Chat, Confluence, their page, the request form, then the other ways, such as “Platform: Google Cloud (Group email: cloud-platform@example.com; Slack: #cloud-platform (https://…); Confluence: …; Request form: …)”. A change to these details gives the skills a new version.</dd></div>
          </dl>
          <ProcessPicture className="guide-fig" process={standardFlow} caption="A rule written once reaches the code twice: as guidance while writing, and as a check when reviewing." />
          <dl className="guide-dl">
            <div><dt>Always current</dt><dd>Publishing a process or standard, or a change to it, produces a new version of its skills; drafts and unpublished changes never reach them. Each version is numbered and names the version of the process or standard it was made from, so a repository holding an old copy can tell. Skills that mention another process or standard follow it too: when that one is renamed they get the new name, and when it is retired or deleted they stop pointing at its skill. A process or standard taken back to draft keeps the skills it had, marked as no longer in use; only the people who may see the draft see them, and downloading one is not counted.</dd></div>
            <div><dt>Where to find them</dt><dd>The <b>Skills</b> tab of a process or standard, and <b>Admin › Skills</b> for all of them. Each says in one sentence what it lets an assistant do; <b>Where to put it</b> folds out where the file belongs in a repository. The page shows what the skill says, without the few header lines only the assistant reads; Copy and Download give the whole file. Each download is counted and shown on the process or standard as its skill downloads. An assistant connected to the portal’s MCP server can also read them itself.</dd></div>
            <div><dt>Extra guidance</dt><dd>Whoever may change the process or standard can add hand-written notes to its skill, on the Skills tab, for example an exemption. They are added to every new version and survive changes of the source.</dd></div>
            <div><dt>Links to other skills</dt><dd>A process or a step can also link to skills kept elsewhere, such as one that updates an infrastructure repository. Those are shown under “Do it faster”.</dd></div>
          </dl>
          <p>The generated files follow the Claude Code layout: skills under <code>.claude/skills/</code>, review agents under <code>.claude/agents/</code>.</p>
        </Section>

        <Section id="agents" title="For agents: the MCP server">
          <p>People use this app. AI assistants and agents can ask the portal the same questions through its <b>MCP server</b> (Model Context Protocol, the usual way to connect an assistant to a source of knowledge). They get the same published content as people: one answer, whoever asks. Where your installation runs it, whoever looks after the portal tells you the address to give your assistant.</p>
          <table className="guide-table">
            <tbody>
              <tr><td><code>search_processes</code>, <code>search_standards</code></td><td>Find what is in use, by words or, where search by meaning is switched on, by meaning (when that does not answer within a few seconds, by words, and the answer says so); narrowed by category, platform, practice, owning team, rigour, tier, environment and language. Retired ones and drafts are not found.</td></tr>
              <tr><td><code>get_process</code>, <code>get_standard</code></td><td>One published process or standard in full, with names and contacts filled in. A retired one is marked and says what replaces it. A standard can be narrowed to what applies to one application.</td></tr>
              <tr><td><code>get_my_steps</code></td><td>Only the steps of one participant, in the order the process runs, with what each waits for, what follows, and whether the assistant may do it itself: never an approval, never a step of someone else.</td></tr>
              <tr><td><code>get_skill</code></td><td>A generated skill or review agent, the latest version unless an older one is asked for.</td></tr>
              <tr><td><code>get_catalog</code></td><td>Teams, practices and platforms with what each is and how to reach it, categories, tools with links, tiers, environments and languages. The owners, and the members of platforms and practices, only where the installation vouches for the assistant.</td></tr>
              <tr><td><code>report_problem</code></td><td>Feedback on a process, a standard, a step or a requirement, in your name, the same as the flag in the app, with the same limits. Offered only where the installation vouches for the assistant and says whom it acts for.</td></tr>
            </tbody>
          </table>
          <dl className="guide-dl">
            <div><dt>Never a draft</dt><dd>An assistant never gets a draft, and cannot tell a draft from something that does not exist. Of something published with unpublished changes it gets the published version, as readers do.</dd></div>
            <div><dt>Limits</dt><dd>Every question gets an answer within 45 seconds. Searches by meaning are limited to 60 a minute for each person or computer; the answer says when to try again. Reports count against the same 30 an hour as reports in the app. An assistant can act only for people of the company’s sign-in domains.</dd></div>
            <div><dt>Rules it is given</dt><dd>When an assistant connects, the portal tells it how to read the content: the first participant of a process is the person it acts for; it waits for approvals and for other teams instead of doing their part; a mandatory process is the only allowed way; a <b>must</b> cannot be waived by it; a retired process or standard is not followed.</dd></div>
            <div><dt>Not yet</dt><dd>Signing in as a person is planned, not built: today the MCP server is reachable only on the computer it runs on, or with one secret shared by every assistant that may use it. Counting what assistants look up, next to the views of people, is planned too.</dd></div>
          </dl>
          <p>The generated skills are the other way to give an assistant this knowledge: put them in the repository it works in. Setting the server up is under <b>Running it locally</b> and <b>Deploying</b>; the full contract is in <code>docs/mcp.md</code>.</p>
        </Section>

        <Section id="roadmap" title="Planned: automation">
          <p>Today a person follows the checklist, and an assistant can already look a process up over the MCP server and read which steps are yours. The next stage, planned and not built, is an agent that follows the process for you: it does your steps with the linked skills, asks you to approve, and tracks the steps of other teams.</p>
          <ProcessPicture className="guide-fig" process={automationFlow} caption="Planned: an AI agent follows the process on your behalf. Looking the process up over MCP works today; the rest is not built. You stay in control of approvals." />
          <p>This is why steps name their participant, tool and kind precisely, and why skills are generated from the same content: the description is already written for a machine to act on.</p>
        </Section>

        <Section id="admin" title="The Admin panel">
          <p><b>Admin</b> in the top bar is where everything is configured. Its sections are listed on the left (on a phone, in one row that scrolls sideways, faded at an edge that has more behind it); the one that is open has its name as the heading, with one line on what it is for. Admins see all of them; people who manage the lists see Lists, Skills and Health.</p>
          <dl className="guide-dl">
            <div><dt><KeyRound size={14} />Access</dt><dd>A list of everybody who has a role, with their name and email and each role on a line of its own, such as “Platform owner for Google Cloud”; <b>Search people</b> finds one by name, email or role. <b>Add person</b> gives a colleague roles by their email. <b>Edit</b> opens one dialog with every role: switch on the ones the person should have and, for Owner, Platform owner, Practice owner, Platform member and Practice member, choose the teams, platforms or practices from the lists (“Another platform” adds one more). Before you save, the dialog says what it gives and what it takes away; however long the list of roles, that line and the buttons stay in view. <b>Delete</b>, a quiet button at the end of the person’s line, removes all of a person’s roles at once, after you confirm; they can still sign in and read like every colleague. A change applies on the person’s next click, without signing in again, and the page confirms it, such as “Sam Consumer’s roles are saved.” An owner of a platform or practice adds and removes its members on the page of that platform or practice, without Admin.</dd></div>
            <div><dt><List size={14} />Lists</dt><dd>Teams, practices, platforms, categories, tools, tiers, environments and languages, with the icons of tools and languages. Each team, practice and platform shows its <b>owners</b> and, for a platform or practice, its <b>members</b>, by name with the email under it, and an admin adds and removes them there; its description and how to reach it are edited there too. While you change the lists, the bar with Undo, Redo and <b>Save changes</b> stays in view above the list. When something in the lists is to fix, a list above them says how many and what to do, and leads to each field (see <b>The lists</b>).</dd></div>
            <div><dt><Bot size={14} />Skills</dt><dd>Every generated skill and review agent, with its versions and extra guidance.</dd></div>
            <div><dt><CalendarCheck size={14} />Health</dt><dd>Reviews that are due (their number in the colour of the worst, with a line such as “6 overdue · 5 due”), open feedback, drafts that were never published, and active documents without an owner or a review rhythm.</dd></div>
            <div><dt>Activity</dt><dd>Who changed what and when: content with the version and its note, including publishing, and throwing away the changes kept in a draft (“threw away the changes kept in the draft of the process”), also when a save or a publish made them unnecessary because nothing had changed (saving changes to a draft is not in it), lists and the icons added to them (“added an icon · PNG image, 64 × 64”), the details of a team, platform or practice (“changed the details of the platform “Google Cloud” · …”, naming what changed), roles and members (“added Sam Consumer to the members of the platform Google Cloud”), skills, feedback that was closed, reopened or deleted by someone other than its author, requests that were made, moved to another state, withdrawn or removed, each named by its title (“asked for a new process: “…””, “changed the state of the request “…””, “removed the request “…””), and the conversions of stored content when a new version of the portal starts. All in words, such as “Jordan Platform published the process “Request a GCP project” · version 2 · changes last saved by Morgan Member”, “took a role from” or “changed the look of the portal”: a process or standard is named by its title (point at it for its id; one deleted since keeps its id), and what the portal did itself starts with “The portal”, such as “The portal imported the sample content”. People are named by their name where the portal knows it (point at it for the email), and a colour code is shown with a small swatch of the colour. Views, bookmarks, upvotes and votes are not in it. The newest entries come first, each with its date and time in your own time zone, such as “2026-11-20 06:44”; “Show older” goes back as far as the log does.</dd></div>
            <div><dt><ChartColumn size={14} />Statistics</dt><dd>How much each process and standard is used, for reporting. Choose a period: 7, 30 or 90 days, a year, or all time. At the top the totals of the period: views, different people, skill downloads, upvotes, feedback given and handled, requests. Then the views per week; a table of every process and standard, with the columns <b>Name</b> (a small mark before it says whether it is a process or a standard), <b>Belongs to</b> (the owning team, or “No owning team”, with its platform and practice below), <b>Views</b>, <b>People</b>, <b>Skill downloads</b>, <b>Upvotes</b>, <b>Feedback open</b> and <b>Feedback handled</b>, which can be sorted by name or any number and narrowed to processes or standards, and fits a laptop screen without scrolling sideways; and the same totals grouped by platform, by practice or by owning team. Open feedback is as it is now; everything else is counted in the period. <b>Download as CSV</b> gives the table as a file for a spreadsheet, with the status as Active, Draft or Retired. A view counts once per person per day, also for admins and editors, and nobody, admins included, can see who viewed what; a skill download counts once per person per skill per day and stands for the use by AI assistants. Days run from midnight to midnight UTC, and the page says what that is in your own time, such as “A day is counted from 01:00 to 01:00 your time (midnight to midnight UTC).” Drafts are included and marked as such. The totals by platform, practice and team end with “No platform”, “No practice” and “No owning team”. When the totals include processes and standards deleted since, a sentence says so, as the table shows only those that still exist. In the views per week, a first or last week that lies only partly in the period is drawn faint, with a dashed edge, and a line under the chart says so: “Faint bars with a dashed edge: weeks only partly inside the period (the first or the last).”</dd></div>
            <div><dt><Palette size={14} />Theming</dt><dd>The name, logo, colours and font everyone sees, and whether new visitors get the light or the dark look; see <b>The look of the portal</b>.</dd></div>
            <div><dt>System</dt><dd>In plain words, how this installation signs people in, its address, whether notifications go to a chat channel and how content is kept. These are set where the portal is installed, not here. <b>For the people who run the portal</b> folds out the names of the settings behind them.</dd></div>
            <div><dt><CodeXml size={14} />Code map</dt><dd>How the portal itself is built, for the admins who review or maintain its code: the one part of the portal written for developers. See <b>The code map</b>.</dd></div>
          </dl>
          <p>Nobody can lock everyone out. The people named as admins in the settings where the portal is installed are marked “set where the portal is installed” and always keep that role; it cannot be taken away in the panel. Among the others, the only admin cannot lose that role or be deleted. You cannot take away your own admin role or delete yourself: ask another admin. The dialog says so before anything is sent.</p>
        </Section>

        <Section id="theming" title="The look of the portal">
          <p>An admin can give the portal the company’s name, logo, colours and font in <b>Admin › Theming</b>. The settings are in groups: <b>Name and logo</b>, <b>Brand and kinds</b>, <b>Buttons</b>, <b>States</b>, <b>Font</b> and <b>Light or dark</b>. Only admins see this section, and the server refuses a change from anyone else. Everything is set in the portal; nothing has to be deployed.</p>
          <ProcessPicture className="guide-fig" process={themeFlow} caption="Changing the look. Nothing changes for anyone until the admin saves; then everybody sees the new look on the next page they open." />
          <dl className="guide-dl">
            <div><dt>Name of the portal</dt><dd>Up to 40 characters; left empty, it is “Process Manager”, as the empty field and the line under it say (“Left empty, the portal is called “Process Manager”. At most 40 characters.”); once you type, a counter shows how many characters are used. It is shown in the top bar (on wide screens, and next to Menu on screens from 600 to 1119 pixels wide; shortened with “…” when it is long; point at it for the whole name), in the browser tab, on the sign-in page, and in what Share copies or puts in an e-mail.</dd></div>
            <div><dt>Logo</dt><dd><b>Choose image…</b> takes a square image: PNG, JPEG, WebP or SVG, at most 64 KB and 512 by 512 pixels, checked like the icons of the lists. It replaces the default mark in the top bar, always shown, also on a phone, and on the sign-in page. The two tiles next to it show it on the light and on the dark top bar; in the dark look an uploaded logo stands on a light plate, so a dark logo stays visible. <b>Use the default mark</b> takes it away.</dd></div>
            <div><dt>Brand and kinds</dt><dd>Start from <b>Ready-made colours</b> (Default, Ocean, Evergreen, Steel, Plum) or set each colour yourself, with the colour picker or as a code such as #0055aa: the <b>Brand colour</b> (links, focus rings, what is selected, and the main buttons unless they have a colour of their own), and the colours of <b>Processes</b> and of <b>Standards</b> (the mark and tag of each). The ready-made colours set only these three: buttons and states keep what you chose for them. <b>Back to the default</b> puts one colour back; a colour that is not set says what it is instead, such as “Follows the brand”, “Neutral” or “Default”.</dd></div>
            <div><dt>Buttons</dt><dd><b>Main buttons</b> are the one main action of a view, such as Publish, Save or Search; without a colour of their own they follow the brand. <b>Other buttons</b> are the outlined buttons beside them, such as Cancel, Discard, Give feedback, Undo in a message, Open, Save draft on the editing bar, and the soft buttons such as a vote on a request or the Words, Meaning and Both switch; without a colour of their own they are neutral grey. Quiet buttons without an outline, icon buttons and the buttons that delete are neither: they stay as they are.</dd></div>
            <div><dt>States</dt><dd><b>Success</b> (published, saved, nothing to fix, done), <b>Warning</b> (review due, drafts, unsaved changes, a step that loops back), <b>Information</b> (notices that only tell something, such as what readers still see; it follows the brand unless it has a colour of its own) and <b>Problem</b> (review overdue, what is to fix, errors, buttons that delete). Without a colour of their own they are green, amber, the brand colour and red. Choose colours that stay far apart: the same colour always means the same, and the icons beside them say it too for people who see colours differently.</dd></div>
            <div><dt>Font</dt><dd><b>Default (Inter)</b> or <b>Roboto</b>, each button written in its own font. Both come with the portal: nothing is fetched from another site, and a browser loads Roboto only when it is chosen. <b>Back to the default</b> goes back to Inter.</dd></div>
            <div><dt>Readable colours</dt><dd>Buttons and other filled parts keep exactly the colour you chose, with black or white text on them, whichever reads better. Text, links and outlines in that colour must stay readable on a light and on a dark page, so the portal makes them darker or lighter where needed; under each colour, “In use: Light #… Dark #…” shows the result, and a line says when it was “Made darker in the light look …”.</dd></div>
            <div><dt>Warnings</dt><dd>A colour that people would mistake for another gets a warning under it that says what they would mix up, for example for a brand colour close to the colour that marks problems: “Buttons that save or approve will look like buttons that delete, and links like error messages.”; for main buttons close to it: “Main buttons will look like buttons that delete: “Publish” and “Delete” will have nearly the same colour.”; for states close to each other: “Warnings and problems will be hard to tell apart: “Review due” and “Review overdue” will have nearly the same colour.”, or, for success and problems that differ almost only in their hue, that people who cannot tell red from green will hardly see a difference. Information close to another state, a state close to the brand or to the colour of processes or standards, a nearly grey colour (for the brand, links are then underlined, so they can be told from text) and processes and standards whose colours are hard to tell apart are warned about too. A warning is given only for a part you chose. Warnings never stop you from saving.</dd></div>
            <div><dt>Light or dark</dt><dd><b>As the device is set</b>, <b>Light</b> or <b>Dark</b>: what people see who have not chosen light or dark themselves with the switch in the top bar. A person’s own choice always wins, for them, in their browser. If your own choice hides what new visitors see, a note says so, with <b>Show me what new visitors see</b>, which forgets your own choice.</dd></div>
            <div><dt>Preview</dt><dd>On the right, the look in light and in dark side by side, each captioned “Preview, light: a sample, nothing in it can be pressed” (and “Preview, dark: …”). It is built from the real parts of the portal and labelled as samples: the top bar with the name and logo, a “Main button”, an “Other button” and a Delete button, “A link”, one notice for each state (“Success: published, everything is saved.” and so on), the marks “Nothing to fix” and “Review due”, a count, the dark editing bar with Save draft and Publish…, “A field, selected” with “Text someone typed”, the Words, Meaning and Both choice, and the cards of a process and a standard, all in the chosen font. It follows every change at once. “Nothing changes for anyone until you save.”</dd></div>
            <div><dt>Undo and redo</dt><dd><b>Undo</b> and <b>Redo</b> at the top of the settings (or Ctrl+Z and Ctrl+Shift+Z) take back or repeat your changes to the look, one at a time, until you save.</dd></div>
            <div><dt>Saving</dt><dd>A bar at the bottom says “Unsaved changes to the look. Everyone sees them once you save.”, with how many warnings there are, such as “2 warnings” (press it to go to the first), <b>Discard</b> and <b>Save for everyone</b>. With warnings, Save for everyone asks once, “Save with 2 warnings?”, with <b>Look at them first</b> and <b>Save anyway</b>; a look without warnings is saved at once; a name that is too long has to be shortened first (“The name can have at most 40 characters: remove 3.”). Everyone sees the saved look on the next page they open. A new visitor’s first page waits for it for at most three seconds, then shows the default look; each browser remembers the last look, so a reload starts with it. If another admin saved a look while you were making yours, nothing is overwritten: “Another admin changed the look” offers <b>Show theirs</b> or <b>Save mine over theirs</b>; Show theirs puts their look on screen, and Undo, at the top of the settings, brings yours back. Every saved change is in <b>Admin › Activity</b>, in words, such as “name “Acme Portal”; brand colour #0055aa; colour of main buttons #1d4ed8; font Roboto; logo added”.</dd></div>
            <div><dt>Back to the default look</dt><dd>At the top, with who changed the look last and when, such as “Last changed by Dana Admin on 2026-11-20 06:44.”, in your own time. After you confirm, everyone sees the name “Process Manager”, the default mark, the default colours and font and the appearance their device is set to, from their next page load.</dd></div>
            <div><dt>What is not part of the look</dt><dd>The shape of corners, the sizes and the icons stay as they are. The look belongs to the installation, not to the content: exporting or importing processes, standards and lists does not carry it, so a new installation is given its look again here.</dd></div>
          </dl>
        </Section>

        <Section id="catalog" title="The lists">
          <p>Processes and standards do not type these in; they pick them from shared lists, so a team is spelled the same everywhere and renaming it once renames it everywhere. Everyone can look them up under <b>Teams &amp; tools</b>; they are changed in <b>Admin › Lists</b>.</p>
          <dl className="guide-dl">
            <div><dt><Users size={14} />Teams</dt><dd>Groups of people. A team maintains processes and issues standards, and takes part in processes, which gives it a lane.</dd></div>
            <div><dt><Compass size={14} />Practices</dt><dd>Disciplines such as cyber security or engineering. They are a list of their own, apart from the teams; a practice and a team may have the same name.</dd></div>
            <div><dt><Boxes size={14} />Platforms</dt><dd>What people build on or get access to, such as Google Cloud, Azure, Apigee or GitHub. A list of their own, apart from teams and practices.</dd></div>
            <div><dt><Tag size={14} />Categories</dt><dd>Subjects that group processes and standards in search and in the list of processes.</dd></div>
            <div><dt>How to reach them</dt><dd>A team, practice or platform can say what it is (up to 600 characters) and how to reach it: Group email, Slack channel and its link, Google Chat space and its link, Confluence page, Their page, Request form, and Other ways to reach them, a free line. Every link must start with http:// or https://. They are shown on its page and in Teams &amp; tools, and they are in the generated skills and the answers to AI agents. Lists managers change them in <b>Admin › Lists</b>; an owner of the group changes them on its page with <b>Edit details</b>.</dd></div>
            <div><dt>Owners and members</dt><dd>Every team, practice and platform shows its owners, and a platform or practice its members; what they may do is under <b>Teams, platforms and practices</b>. In <b>Admin › Lists</b> an admin opens the entry, types an email address under Owners and presses <b>Add owner</b>, or under Members and <b>Add member</b>; the bin next to a person removes them after a question. Both take effect at once. It is the same thing as giving the role under Access, seen from that side. The members are also added and removed by an owner of the platform or practice, on its page. A team without owners has nobody who is asked to review what it owns; a platform or practice without owners is published only by the editors.</dd></div>
            <div><dt>Tools</dt><dd>A step picks its tool from the list. People who manage the lists can add a missing tool straight from the Tool field of a step, on the editing screen.</dd></div>
            <div><dt><Layers size={14} />Tiers</dt><dd>How critical an application is. A process or standard applies to every tier or to chosen ones.</dd></div>
            <div><dt>Environments</dt><dd>Where things run, such as test or production. A requirement can apply to production only.</dd></div>
            <div><dt>Languages</dt><dd>Most content does not depend on the programming language. Some does, such as publishing a Go module.</dd></div>
            <div><dt>Icons</dt><dd>A tool or a language can have an icon, shown next to its name: in the lists under <b>Teams &amp; tools</b>, on the map next to a step’s tool, in the panel of a step and at the top of a step in the checklist, in the Tool field on the editing screen, and next to languages on the cards. In <b>Admin › Lists</b> open the tool or language and press <b>Choose image…</b>; <b>Remove icon</b> takes it away. The image must be PNG, JPEG, WebP or SVG, square and at most 64 KB; a picture at most 512 by 512 pixels, and not a moving one. An SVG may only be a plain drawing: shapes, lines, text, colour gradients, clipping and masks. One with scripts, links, images, animation, or parts that repeat other parts of the drawing (as some drawing programs save it) is refused, as is a very large or deeply nested one; save it again as a plain SVG or use a PNG. A refused image says why. One person can add up to 60 icons an hour. The new icon is kept with the lists when you save them.</dd></div>
          </dl>
          <p><b>Teams &amp; tools</b> shows each entry by its name and one line on how to reach it (such as “Slack #cloud-platform”, else what it is, or “No details yet”), with its owners and members and where it is used. Your own teams, platforms and practices come first, marked “You are an owner” or “You are a member”, and the tab of each list says how many are yours, such as “1 yours”. The name of a team, platform or practice in the details opens its page, as does <b>Open the page of …</b>. The address names the list and the entry, such as <code>#/catalog/platforms/google-cloud</code>, so a link opens it. In <b>Admin › Lists</b> the entry’s <b>Id</b>, the short code processes and standards store, is shown under its name as well. The lists are saved together: a bar above the list and the details, which stays in view under the top bar, holds Undo, Redo and, once something changed, “Unsaved changes to the lists” with <b>Discard</b> and <b>Save changes</b> (“Saved” when there is nothing to save).</p>
          <p>Removing an entry says, for example, “Google Cloud removed · It is gone for everyone once the lists are saved.”, with <b>Undo</b>. An entry that is still used cannot be removed; its page lists the processes and standards that use it. A team, platform or practice that still has owners or members cannot be removed either: “2 people are still its owners or members. Take their roles first, then it can be removed.” The lists have versions like everything else, and two people changing them at once are told about each other.</p>
          <p><b>What is to fix in the lists.</b> When something in the lists cannot be saved, such as a name left empty, a link without https:// or a group email that is not an address, <b>Admin › Lists</b> shows above the lists how many are to fix, such as “2 to fix”, with “The lists can be saved once these are fixed. Press one to go to it.” Each one says what to do and names the list and the entry, such as “Give the team “Cloud Platform team” a name.”, “The link to the Slack channel of the platform “Google Cloud” is not a whole link: write it with https:// at the start.”, “The group email of the practice “Engineering” is not an email address: write one, like team@company.com.” or “Two tools have the id “terraform” (“Terraform” and “Terraform Cloud”): remove one of them.”; an entry without a name is named by its id. Pressing one opens that list and that entry and puts the cursor in the field; the field is outlined and says under it what to do, as on the editing screen. Until all are fixed, <b>Save changes</b> cannot be pressed and says “Fix the problems first”. If the portal refuses a save, the message “The lists could not be saved.” gives the same sentences. Two entries with the same id can only come from an import: changing one leaves the other as it is, and <b>Remove</b> takes away only the one shown (“Another tool has the same id: what uses it keeps the other one.”). <b>Teams &amp; tools</b>, where nothing is changed, shows no such list.</p>
        </Section>

        <Section id="codemap" title="The code map">
          <p><b>Admin › Code map</b> is for the admins who review or maintain the portal itself. It is the one part of the portal written for developers, so it names files, tables and functions. It sorts the portal’s own code into categories in four areas, <b>Data</b>, <b>Server</b>, <b>App</b> and <b>Around the code</b>, and says for each part what it must do, how it works, where it keeps its data and which files make it. A file can be in several categories, each time with what matters there. Only admins see it.</p>
          <dl className="guide-dl">
            <div><dt>Overview</dt><dd><b>The first hour</b> lists six categories to read first, from <b>The tables</b> and <b>From tables to vectors</b> to <b>Rights</b>, each with what it answers. Below, every area has a card per category with its first sentence and how much it holds, such as “16 files · 2 charts · 24 tables”.</dd></div>
            <div><dt>Find a file, a table or a word</dt><dd>Searches the whole map: the categories, the paths of files and what each is for, what the code must do, the tables with their columns, the titles of the charts and the worked examples. A place matches when it holds every word you typed. The results say how many places in how many categories, such as “5 places in 2 categories”, grouped by category with the words marked; each opens at that place. The search stays in the address, and <b>Overview and search</b> at the top of the list of categories brings you back to it.</dd></div>
            <div><dt>A category</dt><dd>Its title and what the part does, then, with a row of links to jump between them: <b>What this part must do</b> (the reviewer’s checklist, shown as review comments), <b>How it works</b> (flow charts, the same as the ones in this guide: drag one, zoom it with its tools or Ctrl + scroll, and <b>Enlarge</b> opens it as large as the window; see <b>Moving around</b> under <b>Reading a process</b>), <b>Tables</b> (each table with its columns, keys, the rules its rows keep, and where it is created and written, as links to those files), <b>Worked examples</b> (the same piece of data at each stage, such as a stored process, the parts it is cut into, its vectors and a search) and <b>Files</b>. Each file shows its path, what it is for, what it must do, the tests that cover it, <b>Also in</b> the other categories that list it, and <b>Open</b>; the file to begin with is marked “Read first”. <b>With comments</b> or <b>Paths only</b> shows the files in full or as a short list; your browser remembers the choice. The other categories stay in a list beside the page, or in a menu on a narrow screen.</dd></div>
            <div><dt>A file</dt><dd>Its path with <b>Copy path</b>, <b>Back to</b> the category, which file of the category it is (“File 3 of 12”) with the previous and the next one, then <b>What this file must do</b> and the file itself with line numbers. Each requirement that points at a line is shown inside the file, above that line, like a comment in a code review; <b>line 120</b> next to it jumps there, and <b>Previous comment</b> and <b>Next comment</b> on the reading bar go from one to the next. <b>Wrap lines</b> breaks long lines instead of scrolling them sideways. When the code has moved and the line a requirement points at is gone, the requirement stays at the top with “Not placed: the line it points at was not found”.</dd></div>
            <div><dt>Where the files can be opened</dt><dd>The text of a file comes from the server, one file at a time, to admins only, and only where the portal runs beside its own source code, as it does with <code>npm run dev</code>. An installed portal has no source code beside it: there the code map still shows every path, requirement, chart and table, and says that the files themselves cannot be opened. Only files kept in the repository’s history can be opened, and only text files of the code: never settings with passwords, keys, installed packages or build output.</dd></div>
            <div><dt>Kept true</dt><dd>A test fails when the map names a file that does not exist, when a requirement points at a line that is not in its file, when a chart does not hold together, or when a new file of the code is in no category. A requirement points at the line that enforces it, so whoever changes that rule changes its sentence in the map too.</dd></div>
          </dl>
        </Section>

        <Section id="architecture" title="How it is built">
          <p>Everything people change in the portal lives in a database: processes, standards and their unpublished changes, the lists with their icons, roles, feedback, requests and the generated skills, and how much each process and standard is used. A small server signs people in, decides what they may do, keeps every version, and regenerates the skills when their source changes.</p>
          <figure className="guide-fig">
            <div className="arch">
              <div className="arch-col">
                <div className="arch-box who"><strong>People</strong><span>in a browser</span></div>
                <div className="arch-box who"><strong>AI agents</strong><span>over the MCP server, a second program on the same database</span></div>
              </div>
              <div className="arch-arrow" aria-hidden="true">→</div>
              <div className="arch-col">
                <div className="arch-group">
                  <em>One container</em>
                  <div className="arch-box core"><strong>The app</strong><span>built, static files</span></div>
                  <div className="arch-box core"><strong>Go server</strong><span>sign-in, roles, content, skills, feedback, requests, search index</span></div>
                </div>
              </div>
              <div className="arch-arrow" aria-hidden="true">→</div>
              <div className="arch-col">
                <div className="arch-box ext"><strong>Postgres</strong><span>content with every version, roles, feedback, skills, activity, requests, views and votes; with pgvector, the search index</span></div>
                <div className="arch-box ext"><strong>Entra ID or Google</strong><span>sign-in</span></div>
                <div className="arch-box ext"><strong>Team channel</strong><span>notifications, optional</span></div>
                <div className="arch-box ext planned"><strong>Files in git</strong><span>first fill, import, export and backup</span></div>
              </div>
            </div>
            <figcaption>What runs where. A change saved in the portal is live at once; no deployment is involved. Not drawn: Vertex AI, used only when search by meaning is set to it.</figcaption>
          </figure>
          <dl className="guide-dl">
            <div><dt>In the database</dt><dd>All content and its history, the changes kept in drafts beside what is stored (unpublished changes, and the newer changes of drafts that still have something to fix), the icons of the lists, roles, feedback, requests, generated skills, the activity log and the look of the portal (Admin › Theming); and the views, bookmarks, upvotes and skill downloads. A view is stored as who viewed what on which day, only to count views and people; it is never shown.</dd></div>
            <div><dt>In the repository</dt><dd>The code, the formats (<code>schema/</code>), and sample content that fills an empty database on its first start.</dd></div>
            <div><dt>Import and export</dt><dd><code>npm run export -- &lt;folder&gt;</code> writes the content and the skills to files, as a backup or to commit. <code>npm run db:import</code> loads the files of the repository over what is stored; files that do not match the format are reported and skipped. <code>npm run db:demo</code> loads the larger demo set from the folder <code>demo/</code> in the same way. An export also removes the files of skills that were withdrawn.</dd></div>
            <div><dt>Two checks</dt><dd>The app checks a document fully before it lets you publish it. The server checks again, also when a draft is stored as the process or standard itself: the rights, the format, that the parts of the document fit together (every step leads to a step that exists, every tier is in the lists), and that the save was made from the newest version. Nothing invalid, unauthorised or outdated is published or stored as a document. Changes kept in a draft (unpublished changes, or the newer changes of a draft that still has something to fix) may be unfinished: they are only checked for size and for text that cannot be stored, and get the full checks when they are published.</dd></div>
            <div><dt>Search by meaning</dt><dd>Off unless <code>PM_EMBEDDINGS</code> is set. Every published process and standard (active or retired) is cut into parts: its summary, each step, each prerequisite, each requirement and the scope (<code>server/internal/chunking</code>). Each part is turned into a vector of numbers by an <b>embeddings provider</b> (<code>server/internal/embedding</code>): <code>builtin</code>, inside the server, which matches words and parts of words rather than meaning, or <code>vertex</code>, Google’s Vertex AI, which compares meaning. The vectors are kept in Postgres with the <b>pgvector</b> extension (<code>server/internal/retrieval</code>). A part’s text carries more than its sentence, so that more questions find it: a requirement also how it is checked, what a reviewer looks for, its examples and where it applies; a step its participant’s description, how long it takes, its sub-process, link and resources; a summary how binding it is, where it applies, the lead time and the standards a process helps to meet. The index follows every publish, retire, unpublish and delete in the background, normally within a moment; a save never waits for it. Only parts that changed are embedded again, and drafts and unpublished changes are never in it. A search turns the question into a vector the same way, finds the closest parts and returns their documents, each with up to three parts that matched; the page then applies its filters and pages to them. The built-in provider ranks by shared words and parts of words: it is for trying the feature and for tests, and an unrelated question can still return results.</dd></div>
          </dl>
          <ProcessPicture className="guide-fig" process={meaningFlow} caption="Search by meaning, from a save to a result. The question is turned into numbers by the same provider and compared with the parts kept in the index." />
          <dl className="guide-dl">
            <div><dt>The MCP server</dt><dd>A second program (<code>server/cmd/mcp</code>, code in <code>server/internal/mcpserver</code>) that reads the same database as the portal and gives AI agents its published content as tools. It never changes tables, never builds or changes the search index (it only searches one the portal built with the same settings), and writes nothing but feedback. It reads only what is published, never drafts or unpublished changes. Until agents can sign in it accepts calls only from its own computer, or calls that carry one shared secret.</dd></div>
            <div><dt>Protection in the browser</dt><dd>The server tells the browser to run only the app’s own code and never to show the app inside another page. For that reason the format checks are not built in the browser but generated from the schemas beforehand (<code>npm run validators</code>).</dd></div>
          </dl>
        </Section>

        <Section id="local" title="Running it locally">
          <p>You need Node 22, Go 1.26 and Docker. One command starts everything: a Postgres container, the server (rebuilt when you change its code) and the app with live reload. An empty database is filled with the sample content of the repository, and with twelve weeks of made-up use - views, upvotes, bookmarks, skill downloads and a few requests in every state - so that the numbers, Your bookmarks, Requests and Admin › Statistics have something to show. That use is added only while there is none at all, and never on a real installation.</p>
          <pre className="guide-code">npm install{"\n"}npm run dev</pre>
          <p>Open <code>http://localhost:5173</code>. Instead of a company sign-in you choose who to be, so you can try each set of rights:</p>
          <dl className="guide-dl">
            <div><dt>Sam Consumer</dt><dd>Reader: follows processes and reports problems.</dd></div>
            <div><dt>Alex Editor</dt><dd>Process editor and Lists manager: edits every process and the lists.</dd></div>
            <div><dt>Casey Owner</dt><dd>Owner for Cloud Platform team: confirms the reviews and answers the feedback of what the team maintains.</dd></div>
            <div><dt>Riley Security</dt><dd>Practice owner for Cyber security and Owner for Cyber Security: edits what belongs to the practice.</dd></div>
            <div><dt>Jordan Platform</dt><dd>Platform owner for Google Cloud, Practice owner for Engineering and Owner for Cloud Platform team: one person in a team, a platform and a practice.</dd></div>
            <div><dt>Morgan Member</dt><dd>Platform member for Google Cloud and Practice member for Engineering: writes drafts there, which an owner publishes.</dd></div>
            <div><dt>Dana Admin</dt><dd>Admin: everything, including who has which role.</dd></div>
          </dl>
          <p>Choosing who to be only works on your own machine: the server refuses to start this way on an address that others can reach.</p>
          <p>Search by meaning is on, with the built-in provider: nothing leaves your machine. Set <code>PM_EMBEDDINGS=off</code> before <code>npm run dev</code> to try the portal without it. The Postgres container is the image <code>pgvector/pgvector:pg16</code>, which has the extension the search index needs.</p>
          <p><code>npm run mcp</code> starts the MCP server for AI agents on <code>127.0.0.1:8081</code>, against the same database, and prints a client configuration to copy. Start <code>npm run dev</code> once first: the portal server prepares and fills the database, and builds the search index.</p>
          <p><code>npm run dev</code> also tells the server where the repository is (<code>PM_SOURCE_DIR</code>), so <b>Admin › Code map</b> opens the files themselves; see <b>The code map</b>. The folder must be a git checkout that belongs to the user who runs the server, with <code>git</code> installed.</p>
          <p><code>npm run db:reset</code> empties the feedback, views, bookmarks, upvotes, skill downloads and requests, and adds all the samples again. <code>npm run db:demo</code> adds a larger demo set - more processes and standards, teams, platforms and practices, with reviews due and overdue - to try the search, its filters and My responsibilities; its lists replace the stored ones, and <code>npm run db:import</code> puts the smaller sample lists back. <code>npm run db:migrate</code> upgrades the database to the current version and says what it did. To use a Postgres you already run instead of Docker, set <code>PM_PG</code>, for example <code>PM_PG=postgres://pm:pm@localhost:5432</code>.</p>
        </Section>

        <Section id="tests" title="Tests">
          <p>Every level is tested, and <code>npm run test:all</code> runs all of it. The same runs on every pull request.</p>
          <table className="guide-table">
            <tbody>
              <tr><td><code>npm test</code></td><td>The logic of the app: both checkers, editing, undo and the rules for saving, what the editing screen says (also after moving or deleting a step, and each problem as an instruction, those of the lists included) and which kind of draft it saves, comparing versions, map layout and zoom (also the size a chart opens at), review dates and “today” counted by the reader’s own day (also in Auckland and Los Angeles around midnight), search and its filters, sorting, pages and cards, search by meaning on the page (when the server is asked, how Both puts the two lists together), the reader’s pages (the tab a process opens on, the last line of a printed page), sharing, icons, requests and statistics, the look of the portal (readable colours, the warnings and the fonts), the AI prompts, rights (who writes drafts, who publishes, the first publication), owners and members, the pages of teams, platforms and practices with their contact details, My responsibilities, and the roles dialog, and that every sample file in the repository and the demo set are valid; and that the code map names only files that exist, points only at lines that are in them, draws charts that hold together and places every file of the code in a category.</td></tr>
              <tr><td><code>npm run test:server</code></td><td>The server against a real Postgres: sign-in (with a stand-in for Entra and Google that signs real tokens), roles and the people with roles, the members and details of teams, platforms and practices, what members may and may not save, content with versions and saves at the same time, unpublished changes and publishing them, the draft of something never published and what people who may not see it are told, icons, the skill generators, feedback, views, bookmarks, upvotes, requests and statistics, the look of the portal, the Admin endpoints, the source files of Admin › Code map with every kind of file it refuses, starting and stopping; cutting documents into parts, the embeddings providers, the search index and its search; the MCP server with its tools and its guard.</td></tr>
              <tr><td><code>npm run test:e2e</code></td><td>A real browser against the real server and database: signing in, following a process, reading a standard, editing both on the editing screen, drafts, unpublished changes and publishing, versions and two people editing at once, feedback, the Admin panel with Theming, skills, AI import; the filters, cards and pages of the lists and the search; the map (Before you start, the hint, diamonds, dragging, the flag on a step); views, skill downloads, upvotes, bookmarks and sharing; requests with their rights; the statistics with the CSV file; and the search switch: Words, Meaning and Both, what each finds, the address, drafts, and what the page says when search by meaning is busy, unavailable or not ready.</td></tr>
              <tr><td><code>npm run validate</code></td><td>The sample files, or a folder written by <code>npm run export</code>, against the schemas and the rules. <code>npm run validate demo</code> checks the demo set as it is loaded: over the sample.</td></tr>
            </tbody>
          </table>
          <p>The browser tests run on their own database, emptied and refilled at the start of every run, without the made-up use of <code>npm run dev</code>. No test calls an outside service: search by meaning runs with the built-in provider, and Vertex AI is tested against a stand-in.</p>
        </Section>

        <Section id="deploy" title="Deploying">
          <p>The <code>Dockerfile</code> builds one container with the server, the app and the sample content. It needs a Postgres database and a few settings:</p>
          <table className="guide-table">
            <tbody>
              <tr><td><code>DATABASE_URL</code></td><td>Where the Postgres database is.</td></tr>
              <tr><td><code>PM_AUTH</code></td><td><code>entra</code> or <code>google</code>. There is no default, so a deployment cannot fall back to the local user picker by accident.</td></tr>
              <tr><td><code>PM_ADMINS</code></td><td>Emails of the first admins. They give everyone else their roles in the Admin panel.</td></tr>
              <tr><td><code>PM_BASE_URL</code></td><td>The public address, starting with <code>https://</code>. Register <code>&lt;address&gt;/auth/callback</code> with Entra or Google.</td></tr>
              <tr><td><code>PM_OIDC_CLIENT_ID</code>, <code>PM_OIDC_CLIENT_SECRET</code></td><td>The app registration.</td></tr>
              <tr><td><code>PM_ENTRA_TENANT</code></td><td>Entra ID: your tenant.</td></tr>
              <tr><td><code>PM_GOOGLE_HOSTED_DOMAIN</code></td><td>Google: your Workspace domain. Without a limit any Google account could sign in, so the server does not start with Google unless this or the next setting is given.</td></tr>
              <tr><td><code>PM_ALLOWED_EMAIL_DOMAINS</code></td><td>Optional, for either provider: only addresses of these domains may sign in.</td></tr>
              <tr><td><code>PM_SESSION_SECRET</code></td><td>At least 32 random characters, for example from <code>openssl rand -base64 48</code>. A placeholder is refused.</td></tr>
              <tr><td><code>PM_NOTIFY</code>, <code>PM_NOTIFY_WEBHOOK_URL</code></td><td>Optional: send notifications to a chat webhook instead of the server log.</td></tr>
              <tr><td><code>PM_LOG_FORMAT</code></td><td>Optional: <code>json</code> for one JSON object per log line.</td></tr>
              <tr><td><code>PM_EMBEDDINGS</code></td><td>Optional: search by meaning. <code>off</code> (the default), <code>builtin</code> (computed in the server; nothing leaves it) or <code>vertex</code> (Google’s Vertex AI, with <code>PM_VERTEX_PROJECT</code> and <code>PM_VERTEX_LOCATION</code>). The size of the vectors, which parts are searched and the lowest score of a match (<code>PM_SEARCH_MIN_SCORE</code>) have settings of their own.</td></tr>
            </tbody>
          </table>
          <p><b>Search by meaning</b> needs the <b>pgvector</b> extension, version 0.5 or later, in the database. The server creates it when its database user may; otherwise it stops with a message naming the statement an administrator has to run once (<code>CREATE EXTENSION IF NOT EXISTS vector;</code>). The server answers at once; the index is built in the background, with its progress in the log, and searches by meaning answer “not ready yet” until it is complete. It then follows every save; <code>server -reindex</code> brings it up to date by hand and says what it did. New settings keep the old index until the new provider has answered; then it is built anew. With <code>vertex</code>, the text of every published process and standard and every search question, from the portal and from agents, is sent to Google Cloud; the server log says so at every start and the search page tells people. Vertex AI has been tried only against a stand-in, not against Google itself, so its first real use needs checking, and the lowest score of a match for it (0.60) is a starting value to tune on real content with <code>PM_SEARCH_MIN_SCORE</code>. The built-in provider ranks by shared words: it is for trying the feature and for tests. Credentials come from the place the server runs (Google’s Application Default Credentials), never from the repository.</p>
          <p><b>The MCP server</b> is in the same container as <code>/app/mcp</code>: run a second container from the image with that as its entrypoint (<code>--entrypoint /app/mcp</code>, or <code>command: ["/app/mcp"]</code>), with the same database and the same search settings as the portal, <code>PM_MCP_ADDR=0.0.0.0:8081</code> and a <code>PM_MCP_SECRET</code>. Without <code>PM_MCP_SECRET</code> it only listens on its own computer; with it, it may listen anywhere and every call must carry that secret.</p>
          <p><b>The code map</b> opens files only where the server is told where its source code is (<code>PM_SOURCE_DIR</code>). The container holds no source code, so a deployment leaves it unset: Admin › Code map then shows the paths, requirements, charts and tables, without the files themselves.</p>
          <p><b>Google Cloud Run.</b> The folder <code>deploy/cloudrun/</code> has what is needed to run the portal as one Cloud Run service behind Identity-Aware Proxy, with the app's pages in a private storage bucket, and its <code>README.md</code> lists the steps in order. Identity-Aware Proxy only decides who may reach the portal; people still sign in to the portal itself. These files have not yet been tried on a real project: their README says what to check first.</p>
          <p>The server answers <code>/healthz</code> when it runs and <code>/readyz</code> when it can also reach the database; use the second to decide whether it gets traffic. Several copies can start at the same time, also on an empty database. When it is asked to stop it finishes the requests it is answering first.</p>
          <p>On its first start with an empty database the server loads the sample content from the container; after that the database is the only source, and a new version of the container never overwrites it. When a new version needs the stored content in another shape, it converts it by itself at its first start, as new versions with a note; earlier versions and the changes kept in drafts are adjusted in place. The full list of settings, the API, the rights and search by meaning are in <code>docs/backend.md</code>, the MCP server in <code>docs/mcp.md</code>; a template is in <code>.env.example</code>.</p>
        </Section>

        <Section id="files" title="Files, schema and checker">
          <p>The formats are defined once, as JSON Schema, and used by the app, the server and the command line.</p>
          <table className="guide-table">
            <tbody>
              <tr><td><code>schema/*.schema.json</code></td><td>The formats of a process, a standard and the lists</td></tr>
              <tr><td><code>src/lib/validators.generated.js</code></td><td>The checks the app runs, generated from the schemas. After changing a schema run <code>npm run validators</code>; a test fails when it was forgotten</td></tr>
              <tr><td><code>processes/</code>, <code>standards/</code>, <code>catalog/</code></td><td>Sample content that fills an empty database; also the layout of an export. The icons of tools and languages are in <code>catalog/icons/</code>, each named after its fingerprint</td></tr>
              <tr><td><code>docs/llm-prompt.md</code>, <code>docs/llm-prompt-standards.md</code></td><td>The AI prompts as shareable files</td></tr>
              <tr><td><code>docs/backend.md</code></td><td>The server: API, settings, rights, database</td></tr>
              <tr><td><code>docs/mcp.md</code></td><td>The MCP server for agents: its tools, settings and guard</td></tr>
              <tr><td><code>server/</code></td><td>The backend</td></tr>
              <tr><td><code>src/codemap/</code></td><td>The code map of Admin › Code map: one file per category, with what each part and each file must do. A new file of the code is placed in a category, or a test fails</td></tr>
              <tr><td><code>.claude/skills/</code></td><td>Instructions for AI coding assistants working on this repository</td></tr>
            </tbody>
          </table>
          <p>The checker runs in the app on every change and from the command line with <code>npm run validate</code>. Beyond the schema it catches, for a process: steps that point nowhere, unknown participants, decisions without labelled branches, missing sub-processes, and steps that can never be reached. For both: a category, platform or practice that is not in the lists. For a standard: duplicate requirement ids, a requirement wider than its standard, and rules checked in review that give reviewers nothing to look for.</p>
        </Section>

        <Section id="docs" title="Keeping this guide current">
          <p>This guide is part of the app’s code (<code>src/components/GuidePage.tsx</code>, with the flow charts in <code>src/guide/flows.ts</code>), so it is changed in the same commit as the feature it describes. An instruction for AI coding assistants, the <code>update-docs</code> skill, makes that the last step of every task that changes code, together with checking what the code map says about the files that changed.</p>
          <p className="muted"><Sparkles size={13} /> The flow charts on this page are themselves processes, drawn by the same map, and they move and zoom like it.</p>
        </Section>
      </article>
    </div>
  );
}
